import type {TopicDeepening} from './topicDeepening';
import {getC1SurvivalLanguageNote} from './c1SurvivalLanguageNotes';
type Local={fr:string;de:string;es:string};
type Q={prompt:string;answers:[string,string,string];explanation:string;evidence:Local};
type Entry={number:number;id:string;title:string;passage:Local;questions:[Q,Q,Q];focus:string;speaking:string;writing:string;steps:[string,string,string,string];model:Local};
const q=(prompt:string,answers:[string,string,string],explanation:string,evidence:Local):Q=>({prompt,answers,explanation,evidence});
const entries:readonly Entry[]=[
{
 number:1,id:'c1-expert-discussion',title:'بحث تخصصی دربارهٔ دسترسی به داده',
 passage:{fr:'Un groupe de chercheurs et de représentants associatifs discute de l’ouverture des données sur les transports. L’association souhaite connaître les temps d’attente par quartier afin de repérer des inégalités. Une chercheuse soutient cet objectif, mais rappelle que de très petits groupes peuvent rendre certaines personnes identifiables. Un responsable propose donc de publier des résultats agrégés et de préciser les limites de cette méthode. Un participant objecte que des moyennes peuvent masquer les expériences des quartiers les moins desservis. Le groupe décide de consulter un spécialiste de la confidentialité et de comparer plusieurs niveaux d’agrégation avant toute publication.',de:'Eine Gruppe aus Forschenden und Vereinsvertretern diskutiert die Öffnung von Verkehrsdaten. Der Verein möchte die Wartezeiten nach Stadtvierteln kennen, um Ungleichheiten zu erkennen. Eine Forscherin unterstützt das Ziel, weist aber darauf hin, dass sehr kleine Gruppen einzelne Personen identifizierbar machen können. Ein Verantwortlicher schlägt daher vor, aggregierte Ergebnisse zu veröffentlichen und die Grenzen dieser Methode offenzulegen. Ein Teilnehmer wendet ein, dass Durchschnittswerte Erfahrungen schlechter angebundener Viertel verdecken können. Die Gruppe beschließt, vor einer Veröffentlichung eine Datenschutzfachperson zu befragen und mehrere Aggregationsstufen zu vergleichen.',es:'Un grupo de investigadores y representantes de asociaciones debate la apertura de datos de transporte. La asociación quiere conocer los tiempos de espera por barrio para detectar desigualdades. Una investigadora apoya ese objetivo, pero recuerda que grupos muy pequeños pueden permitir identificar a personas. Un responsable propone publicar resultados agregados y explicar los límites del método. Un participante objeta que los promedios pueden ocultar las experiencias de los barrios peor atendidos. El grupo decide consultar a un especialista en privacidad y comparar varios niveles de agregación antes de publicar.'},
 questions:[q('هدف انجمن از داده‌های تفکیک‌شده چیست؟',['شناسایی نابرابری زمان انتظار','انتشار نام مسافران','حذف خدمات محله‌ها'],'هدف شناسایی نابرابری میان محله‌هاست.',{fr:'repérer des inégalités',de:'Ungleichheiten zu erkennen',es:'detectar desigualdades'}),q('خطر گروه‌های بسیار کوچک چیست؟',['افزایش تعداد اتوبوس‌ها','امکان شناسایی افراد','نامشخص بودن زمان جلسه'],'گروه کوچک می‌تواند شناسایی افراد را ممکن کند.',{fr:'rendre certaines personnes identifiables',de:'einzelne Personen identifizierbar machen',es:'permitir identificar a personas'}),q('گام پیش از انتشار چیست؟',['انتشار فوری دادهٔ فردی','حذف همهٔ داده‌ها بدون بررسی','مشاورهٔ حریم خصوصی و مقایسهٔ سطح تجمیع'],'پیش از انتشار، مشاوره و مقایسه انجام می‌شود.',{fr:'consulter un spécialiste de la confidentialité et de comparer plusieurs niveaux d’agrégation',de:'eine Datenschutzfachperson zu befragen und mehrere Aggregationsstufen zu vergleichen',es:'consultar a un especialista en privacidad y comparar varios niveles de agregación'})],
 focus:'در بحث تخصصی هدف مشترک، اصطلاح فنی، اعتراض و گام بررسی را تفکیک کنید؛ شفافیت داده با انتشار دادهٔ شخصی برابر نیست.',speaking:'در نقش پژوهشگر، هدف انجمن را بازگو کنید، خطر شناسایی را توضیح دهید و راه بررسی مشترک پیشنهاد کنید.',writing:'یادداشت جلسه‌ای بنویسید که فایده، خطر، اعتراض به میانگین و اقدام پیش از انتشار را ثبت کند.',steps:['هدف داده را شرح دهید.','خطر محرمانگی را مشخص کنید.','اعتراض به میانگین را بازگو کنید.','گام بعدی را بدون ادعای تصویب بنویسید.'],
 model:{fr:'L’association souhaite analyser les temps d’attente par quartier afin de repérer des inégalités. Toutefois, les petits groupes peuvent exposer des personnes. L’agrégation protège mieux la confidentialité, mais les moyennes risquent de masquer certaines expériences. Avant toute publication, nous consulterons une spécialiste et comparerons plusieurs niveaux d’agrégation. Aucune méthode définitive n’a encore été choisie.',de:'Der Verein möchte Wartezeiten nach Vierteln analysieren, um Ungleichheiten zu erkennen. Kleine Gruppen können jedoch einzelne Personen identifizierbar machen. Eine Aggregation schützt die Vertraulichkeit besser, aber Durchschnittswerte können Erfahrungen verdecken. Vor einer Veröffentlichung befragen wir eine Fachperson und vergleichen mehrere Aggregationsstufen. Eine endgültige Methode wurde noch nicht gewählt.',es:'La asociación quiere analizar los tiempos de espera por barrio para detectar desigualdades. Sin embargo, los grupos pequeños pueden permitir identificar a personas. La agregación protege mejor la privacidad, pero los promedios pueden ocultar experiencias. Antes de publicar consultaremos a una especialista y compararemos varios niveles de agregación. Aún no se ha elegido un método definitivo.'}
},
{
 number:2,id:'c1-social-economic-analysis',title:'تحلیل چندوجهی هزینه و دسترسی',
 passage:{fr:'Une ville envisage de réduire le prix des transports le week-end. Les commerçants espèrent attirer davantage de visiteurs, tandis que certaines associations demandent aussi une meilleure fréquence dans les quartiers éloignés. Un rapport fictif estime le coût de la réduction tarifaire, mais ne prévoit pas les changements de fréquentation. Une élue souligne que l’effet économique dépendra des comportements et que les ménages sans accès à une ligne fréquente pourraient peu bénéficier de la mesure. Le conseil demande donc une étude des horaires et une consultation avant de choisir entre une baisse générale et un essai ciblé.',de:'Eine Stadt erwägt, am Wochenende die Fahrpreise zu senken. Geschäftsleute hoffen auf mehr Besucher, während einige Vereine auch häufigere Verbindungen in entlegenen Vierteln fordern. Ein fiktiver Bericht schätzt die Kosten der Preissenkung, sagt aber keine Änderungen der Fahrgastzahlen voraus. Eine Stadträtin betont, dass die wirtschaftliche Wirkung vom Verhalten abhängt und Haushalte ohne häufige Verbindung möglicherweise wenig profitieren. Der Rat verlangt daher eine Untersuchung der Fahrpläne und eine Befragung, bevor er zwischen einer allgemeinen Senkung und einem gezielten Test entscheidet.',es:'Una ciudad estudia reducir el precio del transporte los fines de semana. Los comerciantes esperan atraer más visitantes, mientras algunas asociaciones piden también mayor frecuencia en barrios alejados. Un informe ficticio estima el coste de la rebaja, pero no predice cambios en el número de pasajeros. Una concejala señala que el efecto económico dependerá del comportamiento y que los hogares sin una línea frecuente podrían beneficiarse poco. Por ello el consejo solicita estudiar los horarios y realizar una consulta antes de elegir entre una rebaja general y una prueba focalizada.'},
 questions:[q('انجمن‌ها علاوه بر کاهش قیمت چه می‌خواهند؟',['تردد بیشتر در محله‌های دور','افزایش قیمت برای همه','حذف مسیرهای دور'],'آنها فراوانی بیشتر خدمت در محله‌های دور را می‌خواهند.',{fr:'une meilleure fréquence dans les quartiers éloignés',de:'häufigere Verbindungen in entlegenen Vierteln',es:'mayor frecuencia en barrios alejados'}),q('گزارش کدام مورد را پیش‌بینی نمی‌کند؟',['هزینهٔ تخفیف','تغییر تعداد مسافران','وجود قیمت فعلی'],'گزارش تغییر استفاده را پیش‌بینی نمی‌کند.',{fr:'ne prévoit pas les changements de fréquentation',de:'sagt aber keine Änderungen der Fahrgastzahlen voraus',es:'no predice cambios en el número de pasajeros'}),q('پیش از انتخاب گزینه‌ها چه درخواستی شده؟',['تصویب فوری تخفیف دائمی','حذف نظرسنجی','مطالعهٔ ساعت‌ها و مشورت'],'مطالعه و مشورت پیش از انتخاب درخواست شده است.',{fr:'une étude des horaires et une consultation',de:'eine Untersuchung der Fahrpläne und eine Befragung',es:'estudiar los horarios y realizar una consulta'})],
 focus:'پیامد اقتصادی، توزیع دسترسی و محدودیت پیش‌بینی را جدا کنید؛ برآورد هزینه به تنهایی منفعت را ثابت نمی‌کند.',speaking:'برای شورا پیامدهای اقتصادی و توزیعی دو گزینه را مقایسه و دادهٔ لازم را معرفی کنید.',writing:'تحلیلی کوتاه دربارهٔ تخفیف عمومی و آزمون هدفمند با محدودیت داده و توصیهٔ مشروط بنویسید.',steps:['سیاست پیشنهادی را معرفی کنید.','دغدغهٔ دو گروه را مقایسه کنید.','حدود برآورد را توضیح دهید.','مطالعهٔ لازم پیش از انتخاب را پیشنهاد دهید.'],
 model:{fr:'La baisse des tarifs pourrait attirer des visiteurs, mais son effet sur la fréquentation n’est pas encore estimé. Les habitants éloignés risquent de peu en profiter si les lignes restent peu fréquentes. Une réduction générale et un essai ciblé doivent donc être comparés à partir des coûts et des horaires. Avant toute décision, il faut consulter les usagers et étudier l’accès réel aux services.',de:'Niedrigere Preise könnten Besucher anziehen, aber ihre Wirkung auf die Fahrgastzahlen ist noch nicht geschätzt. Bewohner entlegener Viertel profitieren möglicherweise wenig, wenn Verbindungen selten bleiben. Eine allgemeine Senkung und ein gezielter Test sollten anhand von Kosten und Fahrplänen verglichen werden. Vor einer Entscheidung müssen Nutzer befragt und der tatsächliche Zugang untersucht werden.',es:'La rebaja podría atraer visitantes, pero aún no se ha estimado su efecto sobre la demanda. Los habitantes de barrios alejados podrían beneficiarse poco si las líneas siguen siendo poco frecuentes. Conviene comparar una rebaja general y una prueba focalizada según sus costes y horarios. Antes de decidir hay que consultar a los usuarios y estudiar el acceso real al servicio.'}
},
{
 number:3,id:'c1-evidence-defense',title:'دفاع از دیدگاه با شاهد و محدودیت',
 passage:{fr:'Une équipe propose d’installer des points d’eau dans une gare. Pendant une semaine de chaleur, des bénévoles ont compté cent demandes d’eau, mais ils n’ont pas compté les voyageurs qui apportaient déjà une bouteille. Léa utilise ce relevé pour défendre une étude de faisabilité, non pour affirmer que tous les voyageurs ont besoin d’un point d’eau. Un membre demande si les coûts d’entretien seront couverts. Léa reconnaît qu’ils sont inconnus et propose de demander deux devis ainsi que des données sur l’accès à l’eau existant. Le groupe accepte d’examiner ces informations, sans approuver encore l’installation.',de:'Ein Team schlägt Trinkwasserstellen in einem Bahnhof vor. Während einer heißen Woche zählten Freiwillige hundert Anfragen nach Wasser, erfassten aber nicht, wie viele Reisende bereits eine Flasche mitbrachten. Lea nutzt diese Beobachtung, um eine Machbarkeitsprüfung zu begründen, nicht um zu behaupten, dass alle Reisenden Wasserstellen brauchen. Ein Mitglied fragt nach den laufenden Kosten. Lea räumt ein, dass diese unbekannt sind, und schlägt zwei Angebote sowie Daten zum bestehenden Zugang zu Wasser vor. Die Gruppe prüft die Informationen, genehmigt die Installation aber noch nicht.',es:'Un equipo propone instalar puntos de agua en una estación. Durante una semana de calor, unos voluntarios contaron cien solicitudes de agua, pero no contaron a los viajeros que ya llevaban una botella. Lea utiliza ese registro para defender un estudio de viabilidad, no para afirmar que todos necesitan un punto de agua. Un miembro pregunta si se cubrirán los costes de mantenimiento. Lea reconoce que se desconocen y propone pedir dos presupuestos y datos sobre el acceso existente al agua. El grupo acepta estudiar esa información, sin aprobar todavía la instalación.'},
 questions:[q('مشاهدهٔ داوطلبان چه بود؟',['صد درخواست آب در یک هفتهٔ گرم','صد بطری فروخته‌شده به همه','نبود هیچ درخواست'],'صد درخواست در هفته‌ای گرم شمارش شد.',{fr:'cent demandes d’eau',de:'hundert Anfragen nach Wasser',es:'cien solicitudes de agua'}),q('لیا از مشاهده برای دفاع از چه چیزی استفاده می‌کند؟',['نصب قطعی بدون بررسی','مطالعهٔ امکان‌سنجی','این ادعا که همه نیاز یکسان دارند'],'مشاهده مبنای بررسی امکان‌سنجی است.',{fr:'défendre une étude de faisabilité',de:'eine Machbarkeitsprüfung zu begründen',es:'defender un estudio de viabilidad'}),q('گروه دربارهٔ نصب چه تصمیمی گرفته؟',['نصب را تصویب کرده','آن را برای همیشه ممنوع کرده','فقط بررسی اطلاعات را پذیرفته است'],'بررسی اطلاعات پذیرفته شده اما نصب تصویب نشده است.',{fr:'sans approuver encore l’installation',de:'genehmigt die Installation aber noch nicht',es:'sin aprobar todavía la instalación'})],
 focus:'قدرت ادعا را با گسترهٔ شواهد هماهنگ کنید و به اعتراض مربوط به هزینه پاسخ دهید، بدون اینکه مطالعه را تصمیم نهایی بدانید.',speaking:'در نقش لیا با شاهد محدود از مطالعه دفاع کنید و به پرسش هزینه پاسخ دهید.',writing:'استدلالی با مشاهده، محدودیت، اعتراض و درخواست اطلاعات بنویسید.',steps:['پیشنهاد و شاهد را بیان کنید.','محدودیت مشاهده را روشن کنید.','به هزینهٔ نامعلوم پاسخ دهید.','تصمیم باز را از تصویب نصب جدا کنید.'],
 model:{fr:'Cent demandes pendant une semaine chaude justifient une étude de faisabilité, mais elles ne prouvent pas que tous les voyageurs ont besoin d’eau. Nous n’avons pas compté ceux qui avaient déjà une bouteille et les coûts d’entretien restent inconnus. Je propose de demander deux devis et de vérifier l’accès existant. Ces données permettront de décider sans présumer que l’installation est approuvée.',de:'Hundert Anfragen in einer heißen Woche rechtfertigen eine Machbarkeitsprüfung, belegen aber keinen Bedarf aller Reisenden. Wer bereits eine Flasche mitbrachte, wurde nicht gezählt, und die laufenden Kosten sind unbekannt. Ich schlage zwei Angebote und eine Prüfung des bestehenden Zugangs vor. Diese Daten ermöglichen eine Entscheidung, ohne die Installation bereits als genehmigt darzustellen.',es:'Cien solicitudes durante una semana de calor justifican un estudio de viabilidad, pero no prueban que todos los viajeros necesiten agua. No se contó a quienes ya llevaban una botella y se desconocen los costes de mantenimiento. Propongo solicitar dos presupuestos y revisar el acceso existente. Esos datos permitirán decidir sin presentar la instalación como aprobada.'}
},
{
 number:5,id:'c1-audience-persuasion',title:'اقناع مخاطبان با اولویت‌های متفاوت',
 passage:{fr:'Une équipe souhaite tester une collecte séparée des déchets dans un bâtiment. Le gestionnaire s’inquiète des coûts, tandis que les employés veulent savoir si le tri compliquera leur travail. Pour le gestionnaire, Nora prépare une estimation budgétaire et précise qu’elle ne comprend pas encore les frais de maintenance. Pour les employés, elle propose une démonstration et une période d’essai avec retour anonyme. Elle présente les mêmes limites aux deux groupes et ne promet aucune économie avant mesure. La décision sur le test dépendra de la disponibilité du personnel et de l’accord du propriétaire.',de:'Ein Team möchte die getrennte Abfallsammlung in einem Gebäude testen. Die Hausverwaltung sorgt sich um Kosten, während Beschäftigte wissen möchten, ob die Trennung ihre Arbeit erschwert. Für die Verwaltung erstellt Nora eine Kostenschätzung und weist darauf hin, dass die Wartungskosten noch fehlen. Den Beschäftigten schlägt sie eine Vorführung und einen Test mit anonymen Rückmeldungen vor. Sie nennt beiden Gruppen dieselben Grenzen und verspricht vor einer Messung keine Einsparungen. Der Test hängt von verfügbaren Mitarbeitenden und der Zustimmung des Eigentümers ab.',es:'Un equipo quiere probar la recogida separada de residuos en un edificio. La administración se preocupa por los costes, mientras los empleados quieren saber si separar los residuos complicará su trabajo. Para la administración, Nora prepara una estimación e indica que aún faltan los costes de mantenimiento. Para los empleados propone una demostración y una prueba con comentarios anónimos. Explica las mismas limitaciones a ambos grupos y no promete ahorros antes de medirlos. La prueba dependerá del personal disponible y de la aprobación del propietario.'},
 questions:[q('نگرانی اصلی مدیریت ساختمان چیست؟',['هزینه‌ها','تغییر نام ساختمان','انتشار آمار هوا'],'مدیریت دربارهٔ هزینه نگران است.',{fr:'Le gestionnaire s’inquiète des coûts',de:'Die Hausverwaltung sorgt sich um Kosten',es:'La administración se preocupa por los costes'}),q('برای کارکنان چه اقدامی پیشنهاد می‌شود؟',['توافق قطعی بدون آزمایش','نمایش و آزمایش با بازخورد ناشناس','افزایش ساعات بدون مشورت'],'نمایش و دورهٔ آزمایشی با بازخورد ناشناس پیشنهاد شده است.',{fr:'une démonstration et une période d’essai avec retour anonyme',de:'eine Vorführung und einen Test mit anonymen Rückmeldungen',es:'una demostración y una prueba con comentarios anónimos'}),q('وعدهٔ صرفه‌جویی چه وضعیتی دارد؟',['قطعی و تضمین‌شده است','توسط مالک تأیید شده است','پیش از اندازه‌گیری وعده داده نمی‌شود'],'صرفه‌جویی قبل از سنجش وعده داده نمی‌شود.',{fr:'ne promet aucune économie avant mesure',de:'verspricht vor einer Messung keine Einsparungen',es:'no promete ahorros antes de medirlos'})],
 focus:'استدلال را با دغدغهٔ مخاطب تطبیق دهید، اما محدودیت‌ها را برای همه یکسان و صادقانه بیان کنید.',speaking:'برای مدیر و کارکنان دو معرفی متفاوت از آزمون ارائه دهید، بدون وعدهٔ صرفه‌جویی اثبات‌نشده.',writing:'دو پیام بنویسید که به اولویت هر گروه، محدودیت هزینه و شرط اجرای آزمون پاسخ دهد.',steps:['هدف آزمون را مشخص کنید.','برای مدیریت از هزینه و محدودیت بگویید.','برای کارکنان نمایش و بازخورد را توضیح دهید.','شرط اجرا و نبود صرفه‌جویی تضمین‌شده را حفظ کنید.'],
 model:{fr:'À la direction : nous proposons un essai de tri ; l’estimation reste incomplète car la maintenance n’est pas chiffrée. Aucune économie n’est garantie. Aux employés : une démonstration et un retour anonyme permettront d’évaluer la charge de travail. Dans les deux cas, le test dépend de la disponibilité du personnel et de l’accord du propriétaire.',de:'An die Verwaltung: Wir schlagen einen Trennungstest vor; die Kostenschätzung ist ohne Wartung noch unvollständig. Einsparungen sind nicht garantiert. An die Beschäftigten: Eine Vorführung und anonyme Rückmeldungen helfen, den Arbeitsaufwand zu bewerten. Für beide gilt: Der Test hängt von Personal und Zustimmung des Eigentümers ab.',es:'A la administración: proponemos una prueba de separación; la estimación está incompleta porque falta el mantenimiento. No se garantizan ahorros. A los empleados: una demostración y comentarios anónimos permitirán valorar la carga de trabajo. En ambos casos la prueba depende del personal disponible y de la aprobación del propietario.'}
},
{
 number:6,id:'c1-management-meeting',title:'جلسهٔ مدیریتی و تصمیم مشروط',
 passage:{fr:'Le comité d’un centre culturel examine deux projets pour le prochain trimestre : prolonger les horaires ou organiser des activités mobiles. Le budget disponible ne suffit pas aux deux propositions complètes. Avant de voter, la présidente demande à chaque responsable de présenter les coûts et les risques. Les données sur les horaires sont prêtes, mais le devis des activités mobiles manque encore. Le comité décide de demander ce devis avant vendredi et de reporter le choix à lundi. Il autorise uniquement la préparation des documents, pas l’engagement de dépenses.',de:'Der Ausschuss eines Kulturzentrums prüft zwei Vorhaben für das nächste Quartal: längere Öffnungszeiten oder mobile Veranstaltungen. Das vorhandene Budget reicht nicht für beide vollständigen Vorschläge. Vor einer Abstimmung bittet die Vorsitzende alle Verantwortlichen um Kosten und Risiken. Die Daten zu den Öffnungszeiten liegen vor, aber das Angebot für mobile Veranstaltungen fehlt noch. Der Ausschuss verlangt es bis Freitag und verschiebt die Wahl auf Montag. Er genehmigt nur die Vorbereitung der Unterlagen, keine Ausgaben.',es:'El comité de un centro cultural examina dos proyectos para el próximo trimestre: ampliar horarios u organizar actividades móviles. El presupuesto disponible no alcanza para las dos propuestas completas. Antes de votar, la presidenta pide a cada responsable que presente costes y riesgos. Los datos de horarios están listos, pero aún falta el presupuesto de las actividades móviles. El comité decide pedirlo antes del viernes y aplazar la elección al lunes. Solo autoriza preparar documentos, no comprometer gastos.'},
 questions:[q('چرا دو طرح کامل هم‌زمان قابل اجرا نیستند؟',['بودجه کافی نیست','هر دو قبلاً لغو شده‌اند','مرکز تعطیل دائمی است'],'بودجه برای هر دو پیشنهاد کامل کافی نیست.',{fr:'Le budget disponible ne suffit pas aux deux propositions complètes',de:'Das vorhandene Budget reicht nicht für beide vollständigen Vorschläge',es:'El presupuesto disponible no alcanza para las dos propuestas completas'}),q('چه اطلاعاتی هنوز موجود نیست؟',['هزینهٔ ساعت‌های فعلی','پیشنهاد قیمت فعالیت‌های سیار','فهرست اعضا'],'پیشنهاد قیمت فعالیت سیار هنوز نرسیده است.',{fr:'le devis des activités mobiles manque encore',de:'das Angebot für mobile Veranstaltungen fehlt noch',es:'aún falta el presupuesto de las actividades móviles'}),q('کدام اقدام مجاز شده است؟',['تعهد هزینهٔ هر دو پروژه','تصویب پروژهٔ سیار','فقط آماده‌سازی مدارک'],'کمیته فقط آماده‌سازی مدارک را مجاز دانسته است.',{fr:'uniquement la préparation des documents, pas l’engagement de dépenses',de:'nur die Vorbereitung der Unterlagen, keine Ausgaben',es:'Solo autoriza preparar documentos, no comprometer gastos'})],
 focus:'در صورت‌جلسه دستور، اطلاعات ناقص، مسئولیت، موعد و مرز اختیار را از تصمیم نهایی جدا کنید.',speaking:'در نقش رئیس جلسه وضعیت دو طرح و تصمیم موقت را اعلام و از مسئول مربوط پیگیری کنید.',writing:'صورت‌جلسهٔ تصمیم موقت با دو طرح، مدرک لازم، موعد و محدودیت هزینه بنویسید.',steps:['دو گزینه و محدودیت بودجه را معرفی کنید.','مدرک هنوز ناموجود را نام ببرید.','موعد دریافت و جلسهٔ بعد را ثبت کنید.','آماده‌سازی مدارک را از تعهد هزینه جدا کنید.'],
 model:{fr:'Le comité a examiné l’extension des horaires et les activités mobiles ; le budget ne permet pas de réaliser les deux projets complets. Les données sur les horaires sont disponibles, mais le devis mobile manque. Il sera demandé avant vendredi et le choix reporté à lundi. Seule la préparation des documents est autorisée ; aucune dépense ne doit être engagée.',de:'Der Ausschuss prüfte längere Öffnungszeiten und mobile Veranstaltungen; das Budget reicht nicht für beide vollständigen Projekte. Die Daten zu den Öffnungszeiten liegen vor, das mobile Angebot fehlt. Es wird bis Freitag angefordert; die Wahl erfolgt am Montag. Nur die Vorbereitung der Unterlagen ist genehmigt, nicht die Bindung von Ausgaben.',es:'El comité examinó la ampliación de horarios y las actividades móviles; el presupuesto no cubre ambos proyectos completos. Los datos de horarios están disponibles, pero falta el presupuesto móvil. Se solicitará antes del viernes y la elección se aplaza al lunes. Solo se autoriza preparar documentos; no deben comprometerse gastos.'}
},
{
 number:7,id:'c1-professional-presentation',title:'ارائهٔ حرفه‌ای دربارهٔ ارزیابی یک خدمت',
 passage:{fr:'Pour présenter un essai de rendez-vous en ligne, Inès prépare une intervention de cinq minutes. Elle commence par le problème : les appels restent difficiles à traiter aux heures de pointe. Elle décrit ensuite l’essai mené dans un seul centre et précise que vingt personnes y ont participé. Douze ont dit que la prise de rendez-vous était plus simple, mais le groupe n’est pas représentatif de tous les usagers. Inès conclut en proposant une enquête accessible par plusieurs canaux avant toute généralisation. Elle prévoit une diapositive lisible et une pause pour les questions.',de:'Für die Präsentation eines Tests zur Online-Terminvergabe bereitet Ines einen fünfminütigen Vortrag vor. Sie beginnt mit dem Problem: Zu Stoßzeiten sind Anrufe schwer zu bearbeiten. Danach beschreibt sie den Test in nur einem Zentrum und nennt zwanzig Teilnehmende. Zwölf sagten, die Terminbuchung sei einfacher gewesen, aber die Gruppe repräsentiert nicht alle Nutzer. Abschließend schlägt Ines eine über mehrere Kanäle zugängliche Befragung vor, bevor das Verfahren ausgeweitet wird. Sie plant eine gut lesbare Folie und eine Pause für Fragen.',es:'Para presentar una prueba de citas en línea, Inés prepara una intervención de cinco minutos. Empieza por el problema: las llamadas son difíciles de atender en horas punta. Después describe la prueba realizada en un solo centro e indica que participaron veinte personas. Doce dijeron que pedir cita resultó más sencillo, pero el grupo no representa a todos los usuarios. Inés concluye proponiendo una encuesta accesible por varios canales antes de generalizar el sistema. Prevé una diapositiva legible y una pausa para preguntas.'},
 questions:[q('مسئلهٔ آغاز ارائه چیست؟',['دشواری پاسخ به تماس‌ها در ساعت شلوغ','کمبود صندلی در سالن','لغو تمام خدمات'],'پاسخ‌گویی به تماس‌ها در ساعات شلوغ دشوار است.',{fr:'les appels restent difficiles à traiter aux heures de pointe',de:'Zu Stoßzeiten sind Anrufe schwer zu bearbeiten',es:'las llamadas son difíciles de atender en horas punta'}),q('محدودیت دادهٔ آزمایش چیست؟',['شرکت‌کنندگان هیچ پاسخی نداده‌اند','گروه نمایندهٔ همهٔ کاربران نیست','آزمایش در تمام مراکز انجام شده است'],'گروه کوچک نمایندهٔ همهٔ کاربران نیست.',{fr:'le groupe n’est pas représentatif de tous les usagers',de:'die Gruppe repräsentiert nicht alle Nutzer',es:'el grupo no representa a todos los usuarios'}),q('پیشنهاد پیش از تعمیم چیست؟',['تعمیم فوری بدون بررسی','حذف دسترسی تلفنی','نظرسنجی از چند کانال قابل دسترس'],'او نظرسنجی چندکاناله را پیشنهاد می‌کند.',{fr:'une enquête accessible par plusieurs canaux avant toute généralisation',de:'eine über mehrere Kanäle zugängliche Befragung vor, bevor das Verfahren ausgeweitet wird',es:'una encuesta accesible por varios canales antes de generalizar el sistema'})],
 focus:'ارائهٔ مؤثر، مسئله، روش، نتیجه، محدودیت و گام بعدی را با نظم و دسترس‌پذیری پیوند می‌دهد.',speaking:'یک ارائهٔ کوتاه با معرفی مسئله، دادهٔ محدود، هشدار دربارهٔ نمونه و دعوت به پرسش اجرا کنید.',writing:'طرح ارائه با مقدمه، نتیجهٔ آزمایش، محدودیت و پیشنهاد بعدی تهیه کنید.',steps:['مسئله و هدف را معرفی کنید.','تعداد و نتیجهٔ آزمایش را بیان کنید.','محدودیت نمونه را توضیح دهید.','پیشنهاد و دعوت به پرسش را اضافه کنید.'],
 model:{fr:'Aujourd’hui, je présente un essai de rendez-vous en ligne destiné à réduire la pression sur les appels. Dans un seul centre, douze des vingt participants ont jugé la démarche plus simple. Ce groupe ne représente pas tous les usagers. Avant toute généralisation, nous proposons une enquête accessible par plusieurs canaux. Je serai heureuse de répondre à vos questions.',de:'Heute stelle ich einen Test zur Online-Terminvergabe vor, der den Druck auf die Telefonannahme verringern soll. In einem Zentrum fanden zwölf von zwanzig Teilnehmenden das Verfahren einfacher. Die Gruppe repräsentiert nicht alle Nutzer. Vor einer Ausweitung schlagen wir eine über mehrere Kanäle zugängliche Befragung vor. Ich beantworte gern Ihre Fragen.',es:'Hoy presento una prueba de citas en línea destinada a reducir la presión sobre las llamadas. En un centro, doce de veinte participantes consideraron más sencillo el trámite. El grupo no representa a todos los usuarios. Antes de generalizarlo proponemos una encuesta accesible por varios canales. Con gusto responderé a sus preguntas.'}
},
{
 number:8,id:'c1-project-defense',title:'دفاع از طرح و پاسخ به پرسش دشوار',
 passage:{fr:'Une équipe présente un projet de jardin sur le toit d’une école. Elle estime que l’espace pourrait servir à des ateliers, mais aucune étude de structure n’a encore été réalisée. Une membre du comité demande si le toit supportera le poids des bacs. La cheffe de projet répond qu’elle ne peut pas le garantir et propose une expertise avant tout achat. Un autre membre interroge le coût de l’entretien pendant les vacances. L’équipe convient de consulter les services concernés et d’ajouter ce coût au budget prévisionnel. Le comité demande une version révisée ; il ne finance pas encore le projet.',de:'Ein Team stellt ein Dachgartenprojekt für eine Schule vor. Der Raum könnte für Workshops genutzt werden, doch eine statische Prüfung wurde noch nicht durchgeführt. Ein Ausschussmitglied fragt, ob das Dach das Gewicht der Beete tragen wird. Die Projektleiterin antwortet, dass sie dies nicht garantieren kann, und schlägt vor jedem Kauf ein Gutachten vor. Ein weiteres Mitglied fragt nach den Pflegekosten während der Ferien. Das Team will die zuständigen Stellen befragen und diese Kosten in den Budgetentwurf aufnehmen. Der Ausschuss verlangt eine überarbeitete Fassung; er finanziert das Projekt noch nicht.',es:'Un equipo presenta un proyecto de huerto en la azotea de una escuela. Considera que el espacio podría servir para talleres, pero aún no se ha realizado un estudio estructural. Un miembro del comité pregunta si la azotea soportará el peso de los recipientes. La jefa del proyecto responde que no puede garantizarlo y propone un informe técnico antes de cualquier compra. Otro miembro pregunta por el coste del mantenimiento durante las vacaciones. El equipo acuerda consultar a los servicios correspondientes e incluir ese coste en el presupuesto previsto. El comité pide una versión revisada; todavía no financia el proyecto.'},
 questions:[q('چه بررسی‌ای هنوز انجام نشده است؟',['بررسی سازهٔ سقف','نوشتن عنوان طرح','تشکیل کمیته'],'بررسی سازه هنوز انجام نشده است.',{fr:'aucune étude de structure n’a encore été réalisée',de:'eine statische Prüfung wurde noch nicht durchgeführt',es:'aún no se ha realizado un estudio estructural'}),q('پاسخ مسئول دربارهٔ تحمل سقف چیست؟',['تحمل سقف را تضمین می‌کند','نمی‌تواند تضمین کند و بررسی پیشنهاد می‌دهد','پرسش را حذف می‌کند'],'او نبود تضمین را می‌پذیرد و بررسی پیشنهاد می‌دهد.',{fr:'elle ne peut pas le garantir et propose une expertise avant tout achat',de:'sie dies nicht garantieren kann, und schlägt vor jedem Kauf ein Gutachten vor',es:'no puede garantizarlo y propone un informe técnico antes de cualquier compra'}),q('کمیته چه تصمیمی گرفته است؟',['تأمین مالی کامل را تصویب کرده','خرید فوری را مجاز کرده','نسخهٔ بازنگری‌شده خواسته و هنوز تأمین مالی نکرده است'],'نسخهٔ بازنگری‌شده خواسته شده و بودجه هنوز تصویب نشده است.',{fr:'demande une version révisée ; il ne finance pas encore le projet',de:'verlangt eine überarbeitete Fassung; er finanziert das Projekt noch nicht',es:'pide una versión revisada; todavía no financia el proyecto'})],
 focus:'پاسخ حرفه‌ای به پرسش دشوار می‌تواند اذعان به ندانستن، اقدام بررسی و زمان پیگیری باشد؛ اطمینان فنی ساختگی ندهید.',speaking:'در نقش مدیر پروژه به دو پرسش سازه و نگهداری پاسخ دهید و گام بعدی را مشخص کنید.',writing:'پاسخی به کمیته بنویسید که دو ریسک و اطلاعات لازم نسخهٔ اصلاح‌شده را توضیح دهد.',steps:['فایدهٔ احتمالی را بیان کنید.','عدم قطعیت سازه را بپذیرید.','بررسی هزینهٔ نگهداری را توضیح دهید.','وضعیت تأمین مالی را قطعی اعلام نکنید.'],
 model:{fr:'Le toit pourrait accueillir des ateliers, mais nous ne pouvons pas garantir sa capacité sans expertise. Nous proposerons donc une étude de structure avant tout achat. Nous consulterons aussi les services concernés sur l’entretien pendant les vacances et intégrerons le coût au budget révisé. Nous transmettrons ces éléments au comité ; le financement n’est pas encore accordé.',de:'Das Dach könnte für Workshops genutzt werden, aber seine Tragfähigkeit können wir ohne Gutachten nicht garantieren. Wir schlagen daher vor jedem Kauf eine statische Prüfung vor. Auch zu den Pflegekosten während der Ferien befragen wir die zuständigen Stellen und ergänzen den Budgetentwurf. Wir reichen die überarbeitete Fassung ein; eine Finanzierung ist noch nicht zugesagt.',es:'La azotea podría servir para talleres, pero no podemos garantizar su capacidad sin un informe técnico. Proponemos estudiar la estructura antes de cualquier compra. También consultaremos a los servicios sobre el mantenimiento durante las vacaciones e incluiremos su coste en el presupuesto revisado. Presentaremos esos datos al comité; la financiación aún no está aprobada.'}
},
{
 number:9,id:'c1-conflict-management',title:'مدیریت اختلاف بر سر شیفت‌ها',
 passage:{fr:'Deux équipes se disputent l’utilisation d’une salle de réunion le jeudi. L’une affirme qu’elle accueille des visiteurs ; l’autre a besoin d’un espace calme pour former de nouveaux collègues. Le responsable organise une discussion séparant les besoins des accusations personnelles. Il demande d’abord quels horaires sont indispensables et quels aménagements seraient possibles. Les équipes envisagent d’alterner la salle et de réserver un autre espace pour certaines formations, mais l’accessibilité du second lieu reste à vérifier. Aucun accord définitif n’est annoncé avant cette vérification et la consultation des personnes concernées.',de:'Zwei Teams streiten über die Nutzung eines Besprechungsraums am Donnerstag. Das eine empfängt Besucher; das andere benötigt einen ruhigen Ort für die Einarbeitung neuer Kolleginnen und Kollegen. Die Leitung organisiert ein Gespräch, das Bedürfnisse von persönlichen Vorwürfen trennt. Zunächst fragt sie nach unverzichtbaren Zeiten und möglichen Anpassungen. Die Teams erwägen, den Raum abwechselnd zu nutzen und für manche Schulungen einen anderen Ort zu reservieren, dessen Zugänglichkeit noch geprüft werden muss. Vor dieser Prüfung und der Befragung der Betroffenen wird keine endgültige Einigung verkündet.',es:'Dos equipos discuten por el uso de una sala de reuniones los jueves. Uno recibe visitantes; el otro necesita un lugar tranquilo para formar a nuevos compañeros. La responsable organiza una conversación que separa las necesidades de las acusaciones personales. Primero pregunta qué horarios son indispensables y qué ajustes serían posibles. Los equipos consideran alternar la sala y reservar otro espacio para algunas formaciones, pero aún hay que comprobar la accesibilidad del segundo lugar. No se anuncia un acuerdo definitivo antes de esa comprobación y de consultar a las personas afectadas.'},
 questions:[q('دو نیاز اصلی طرفین چیست؟',['پذیرش بازدیدکننده و فضای آرام برای آموزش','خرید خودرو و فروش کتاب','تعطیلی کامل ساختمان'],'یک تیم بازدیدکننده دارد و دیگری فضای آرام آموزشی می‌خواهد.',{fr:'accueille des visiteurs ; l’autre a besoin d’un espace calme',de:'empfängt Besucher; das andere benötigt einen ruhigen Ort',es:'recibe visitantes; el otro necesita un lugar tranquilo'}),q('دربارهٔ فضای دوم چه چیزی باید بررسی شود؟',['رنگ لوگو','دسترس‌پذیری','برنامهٔ تعطیلی سال گذشته'],'دسترس‌پذیری فضای دوم هنوز بررسی نشده است.',{fr:'l’accessibilité du second lieu reste à vérifier',de:'dessen Zugänglichkeit noch geprüft werden muss',es:'aún hay que comprobar la accesibilidad del segundo lugar'}),q('وضعیت توافق نهایی چیست؟',['قطعی و اجراشده است','به مدیر بیرونی واگذار شده است','پیش از بررسی و مشورت اعلام نمی‌شود'],'پیش از بررسی و مشورت توافق نهایی اعلام نمی‌شود.',{fr:'Aucun accord définitif n’est annoncé avant cette vérification',de:'keine endgültige Einigung verkündet',es:'No se anuncia un acuerdo definitivo antes de esa comprobación'})],
 focus:'در تعارض، نیاز و محدودیت را از قضاوت شخصی جدا کنید و گزینهٔ مشروط را توافق قطعی جا نزنید.',speaking:'در نقش میانجی، نیاز هر تیم را بازگو و گزینه‌ای مشروط به بررسی دسترسی پیشنهاد کنید.',writing:'صورت‌جلسه‌ای بدون قضاوت شخصی بنویسید که نیازها و مراحل باز را ثبت کند.',steps:['نیاز هر تیم را بیان کنید.','گزینهٔ تقسیم زمان را توضیح دهید.','دسترس‌پذیری را شرط بررسی بدانید.','مشورت و وضعیت باز توافق را ثبت کنید.'],
 model:{fr:'Les deux équipes ont besoin de la salle le jeudi : l’une reçoit des visiteurs et l’autre forme des collègues dans un espace calme. Elles envisagent une alternance et un autre lieu pour certaines formations. L’accessibilité de ce lieu doit être vérifiée et les personnes concernées consultées. Aucun accord définitif ne sera annoncé avant ces étapes.',de:'Beide Teams benötigen den Raum am Donnerstag: eines für Besucher, das andere für eine ruhige Einarbeitung. Sie erwägen eine abwechselnde Nutzung und einen anderen Ort für einzelne Schulungen. Dessen Zugänglichkeit muss geprüft und die Betroffenen müssen befragt werden. Vor diesen Schritten wird keine endgültige Einigung verkündet.',es:'Los dos equipos necesitan la sala el jueves: uno para recibir visitantes y otro para formar a compañeros en un espacio tranquilo. Consideran alternar su uso y buscar otro lugar para algunas formaciones. Hay que comprobar su accesibilidad y consultar a las personas afectadas. No se anunciará un acuerdo definitivo antes de esos pasos.'}
},
{
 number:11,id:'c1-report-critique',title:'نقد گزارش حرفه‌ای و روش آن',
 passage:{fr:'Un rapport interne recommande de fermer un guichet le mardi parce que le nombre de visites y est faible. Il indique le total hebdomadaire, mais ne fournit pas les chiffres par jour ni la période de collecte. Une responsable remarque aussi que les personnes qui ont renoncé à venir ne figurent pas dans le comptage. Elle ne rejette pas immédiatement la recommandation : elle demande les données quotidiennes, les coûts et une consultation des usagers avant d’évaluer les options. Le service accepte de compléter le rapport, sans fixer de date de fermeture.',de:'Ein interner Bericht empfiehlt, einen Schalter dienstags zu schließen, weil dort angeblich wenige Besuche stattfinden. Er nennt die Wochensumme, aber weder Tageszahlen noch den Erhebungszeitraum. Eine Verantwortliche merkt außerdem an, dass Personen, die auf einen Besuch verzichtet haben, nicht gezählt wurden. Sie lehnt die Empfehlung nicht sofort ab: Vor der Bewertung verlangt sie Tagesdaten, Kosten und eine Nutzerbefragung. Der Dienst ergänzt den Bericht, ohne einen Schließungstermin festzulegen. Die Beschäftigten sollen die erforderlichen Angaben zusammentragen.',es:'Un informe interno recomienda cerrar una ventanilla los martes porque supuestamente recibe pocas visitas. Indica el total semanal, pero no proporciona cifras por día ni el periodo de recogida. Una responsable observa además que el recuento no incluye a las personas que renunciaron a acudir. No rechaza de inmediato la recomendación: solicita datos diarios, costes y una consulta a los usuarios antes de evaluar las opciones. El servicio acepta completar el informe sin fijar una fecha de cierre.'},
 questions:[q('کدام داده در گزارش غایب است؟',['شمار روزانه و بازهٔ گردآوری','کل هفتگی','اصل پیشنهاد بستن باجه'],'گزارش کل هفتگی را دارد، اما دادهٔ روزانه و بازه را ندارد.',{fr:'ne fournit pas les chiffres par jour ni la période de collecte',de:'weder Tageszahlen noch den Erhebungszeitraum',es:'no proporciona cifras por día ni el periodo de recogida'}),q('چه افرادی در شمارش نیامده‌اند؟',['تمام مراجعان حاضر','افرادی که از مراجعه منصرف شدند','تمام کارکنان ساختمان'],'افرادی که منصرف شدند در شمارش نیستند.',{fr:'les personnes qui ont renoncé à venir ne figurent pas dans le comptage',de:'Personen, die auf einen Besuch verzichtet haben, nicht gezählt wurden',es:'no incluye a las personas que renunciaron a acudir'}),q('گام بعدی چیست؟',['بستن فوری باجه','رد قطعی گزارش بدون داده','تکمیل گزارش و مشورت پیش از ارزیابی'],'اطلاعات تکمیل و پیش از ارزیابی مشورت می‌شود.',{fr:'accepte de compléter le rapport, sans fixer de date de fermeture',de:'ergänzt den Bericht, ohne einen Schließungstermin festzulegen',es:'acepta completar el informe sin fijar una fecha de cierre'})],
 focus:'در نقد گزارش، دادهٔ موجود، دادهٔ غایب و سوگیری انتخاب را جدا کنید؛ نقص سند به معنی نادرستی قطعی توصیه نیست.',speaking:'نقص گزارش را محترمانه توضیح دهید و داده‌های لازم برای تصمیم را درخواست کنید.',writing:'یادداشت نقدی دربارهٔ ادعا، محدودیت شمارش و مدارک تکمیلی بنویسید.',steps:['توصیهٔ گزارش را بازگو کنید.','داده‌های روزانه و بازهٔ غایب را مشخص کنید.','افراد حذف‌شده از شمارش را توضیح دهید.','مدارک و مشورت پیش از تصمیم را پیشنهاد کنید.'],
 model:{fr:'Le rapport propose de fermer le guichet le mardi, mais le total hebdomadaire ne permet pas de vérifier la fréquentation de ce jour. La période de collecte manque et les personnes ayant renoncé à venir ne sont pas comptées. Avant de juger la recommandation, il faudrait obtenir les données quotidiennes et les coûts, puis consulter les usagers. Aucune date de fermeture n’est fixée.',de:'Der Bericht empfiehlt die Schließung am Dienstag, doch die Wochensumme belegt die Besucherzahl dieses Tages nicht. Der Erhebungszeitraum fehlt und Personen, die auf einen Besuch verzichteten, wurden nicht erfasst. Vor einer Bewertung sollten Tagesdaten und Kosten eingeholt und Nutzer befragt werden. Ein Schließungstermin steht nicht fest.',es:'El informe recomienda cerrar el martes, pero el total semanal no permite comprobar la afluencia de ese día. Falta el periodo de recogida y no se contó a quienes renunciaron a acudir. Antes de valorar la recomendación convendría obtener datos diarios y costes, y consultar a los usuarios. No se ha fijado una fecha de cierre.'}
},
{
 number:12,id:'c1-evaluate-sources',title:'ترکیب و ارزیابی دو منبع متفاوت',
 passage:{fr:'Une équipe compare deux sources sur une nouvelle piste cyclable. Un comptage municipal enregistre quatre cents passages sur trois jours, sans identifier les personnes. Une enquête associative recueille trente réponses volontaires sur le sentiment de sécurité ; vingt répondants se disent rassurés. Les deux sources répondent à des questions différentes et n’utilisent pas le même dénominateur. L’équipe précise que quatre cents passages ne signifient pas quatre cents cyclistes et que trente avis volontaires ne représentent pas forcément tous les usagers. Elle recommande un comptage plus long et une enquête aux heures variées.',de:'Ein Team vergleicht zwei Quellen zu einem neuen Radweg. Eine kommunale Zählung erfasst vierhundert Fahrten an drei Tagen, ohne Personen zu identifizieren. Eine Vereinsbefragung sammelt dreißig freiwillige Antworten zum Sicherheitsgefühl; zwanzig Befragte fühlen sich sicherer. Die Quellen beantworten unterschiedliche Fragen und haben nicht denselben Nenner. Das Team betont, dass vierhundert Fahrten nicht vierhundert Radfahrende bedeuten und dreißig freiwillige Meinungen nicht unbedingt alle Nutzer repräsentieren. Es empfiehlt eine längere Zählung und eine Befragung zu unterschiedlichen Zeiten.',es:'Un equipo compara dos fuentes sobre un nuevo carril bici. Un recuento municipal registra cuatrocientos pasos durante tres días sin identificar a las personas. Una encuesta de una asociación recoge treinta respuestas voluntarias sobre la sensación de seguridad; veinte participantes dicen sentirse más seguros. Las fuentes responden a preguntas diferentes y no tienen el mismo denominador. El equipo aclara que cuatrocientos pasos no equivalen a cuatrocientos ciclistas y que treinta opiniones voluntarias no representan necesariamente a todos los usuarios. Recomienda un recuento más largo y una encuesta en horarios variados.'},
 questions:[q('منبع شهرداری چه چیزی را ثبت می‌کند؟',['۴۰۰ عبور در سه روز','۴۰۰ دوچرخه‌سوار یکتا','۳۰ نظر دربارهٔ امنیت'],'شمارش مربوط به عبورهاست نه افراد یکتا.',{fr:'quatre cents passages sur trois jours',de:'vierhundert Fahrten an drei Tagen',es:'cuatrocientos pasos durante tres días'}),q('۲۰ پاسخ مثبت از چه گروهی است؟',['تمام ساکنان','۳۰ پاسخ‌دهندهٔ داوطلب','۴۰۰ دوچرخه‌سوار یکتا'],'۲۰ نفر از ۳۰ پاسخ‌دهندهٔ داوطلب چنین گفتند.',{fr:'trente réponses volontaires sur le sentiment de sécurité ; vingt répondants',de:'dreißig freiwillige Antworten zum Sicherheitsgefühl; zwanzig Befragte',es:'treinta respuestas voluntarias sobre la sensación de seguridad; veinte participantes'}),q('چه تکمیلی پیشنهاد شده است؟',['حذف منبع دوم','تصمیم قطعی بر پایهٔ دو عدد','شمارش طولانی‌تر و نظرسنجی در ساعت‌های متنوع'],'گروه شمارش طولانی‌تر و نظرسنجی متنوع را پیشنهاد می‌کند.',{fr:'un comptage plus long et une enquête aux heures variées',de:'eine längere Zählung und eine Befragung zu unterschiedlichen Zeiten',es:'un recuento más largo y una encuesta en horarios variados'})],
 focus:'منبع، واحد سنجش، مخرج و محدودیت نمایندگی را حفظ کنید؛ عبور با فرد و نظر داوطلب با کل کاربران یکی نیست.',speaking:'دو منبع را برای شورا خلاصه کنید و توضیح دهید چرا اعداد را نمی‌توان مستقیم با هم مقایسه کرد.',writing:'ترکیبی از دو منبع با اعداد، واحدها، محدودیت‌ها و پیشنهاد تکمیل بنویسید.',steps:['شمارش شهرداری را با واحد و بازه معرفی کنید.','نظرسنجی و مخرج آن را توضیح دهید.','محدودیت هر منبع را جدا کنید.','پیشنهاد دادهٔ تکمیلی بدهید.'],
 model:{fr:'Le comptage municipal relève quatre cents passages en trois jours, sans identifier les cyclistes. Dans une enquête distincte, vingt des trente répondants volontaires se disent rassurés. Ces résultats ne mesurent pas la même chose : un passage n’est pas une personne et les réponses ne représentent pas nécessairement tous les usagers. Un comptage prolongé et une enquête à des heures variées seraient utiles.',de:'Die kommunale Zählung erfasst vierhundert Fahrten in drei Tagen, ohne Radfahrende zu identifizieren. In einer getrennten Befragung fühlen sich zwanzig von dreißig freiwillig Antwortenden sicherer. Die Ergebnisse messen Unterschiedliches: Eine Fahrt ist keine Person, und die Antworten repräsentieren nicht unbedingt alle Nutzer. Eine längere Zählung und eine Befragung zu verschiedenen Zeiten wären hilfreich.',es:'El recuento municipal registra cuatrocientos pasos en tres días sin identificar a los ciclistas. En una encuesta distinta, veinte de treinta participantes voluntarios se sienten más seguros. Los resultados miden cosas diferentes: un paso no es una persona y las respuestas no representan necesariamente a todos los usuarios. Serían útiles un recuento más largo y una encuesta en distintos horarios.'}
},
{
 number:13,id:'c1-news-discourse',title:'تحلیل خبر و تفاوت تیتر با شاهد',
 passage:{fr:'Un titre fictif annonce : « Le nouveau marché transforme tout le quartier ». Le texte indique pourtant que dix commerçants interrogés ont signalé une hausse de clientèle pendant deux semaines. Il ne précise pas comment ils ont été sélectionnés et ne compare pas les résultats avec ceux d’autres commerces. Une lectrice distingue donc la portée générale du titre des observations limitées de l’article. Elle cherche aussi si une source indépendante a mesuré les effets sur les habitants et les prix. En attendant ces informations, elle décrit la hausse comme un témoignage limité, pas comme une transformation démontrée.',de:'Eine fiktive Überschrift meldet: „Der neue Markt verändert das ganze Viertel.“ Der Text berichtet jedoch, dass zehn befragte Geschäftsleute während zweier Wochen mehr Kundschaft bemerkten. Er erklärt weder ihre Auswahl noch vergleicht er die Ergebnisse mit anderen Geschäften. Eine Leserin unterscheidet daher die allgemeine Aussage der Überschrift von den begrenzten Beobachtungen des Artikels. Sie prüft auch, ob eine unabhängige Quelle Auswirkungen auf Bewohner und Preise gemessen hat. Bis dahin beschreibt sie den Anstieg als begrenzte Rückmeldung, nicht als nachgewiesene Veränderung des gesamten Viertels.',es:'Un titular ficticio anuncia: «El nuevo mercado transforma todo el barrio». Sin embargo, el texto indica que diez comerciantes entrevistados observaron más clientes durante dos semanas. No explica cómo fueron seleccionados ni compara los resultados con otros comercios. Una lectora distingue así el alcance general del titular de las observaciones limitadas del artículo. También busca si una fuente independiente ha medido los efectos en los vecinos y en los precios. Mientras tanto describe el aumento como un testimonio limitado, no como una transformación demostrada.'},
 questions:[q('دادهٔ مقاله به چه گروه و مدتی مربوط است؟',['ده کسبه در دو هفته','همهٔ ساکنان در یک سال','صد فروشگاه در سه ماه'],'مشاهده به ده کسبه در دو هفته محدود است.',{fr:'dix commerçants interrogés ont signalé une hausse de clientèle pendant deux semaines',de:'zehn befragte Geschäftsleute während zweier Wochen mehr Kundschaft bemerkten',es:'diez comerciantes entrevistados observaron más clientes durante dos semanas'}),q('کدام اطلاعات روش‌شناسی روشن نیست؟',['نام بازار','شیوهٔ انتخاب کسبه','وجود تیتر'],'روش انتخاب ده کسبه بیان نشده است.',{fr:'ne précise pas comment ils ont été sélectionnés',de:'Er erklärt weder ihre Auswahl',es:'No explica cómo fueron seleccionados'}),q('خواننده چه نتیجه‌ای می‌گیرد؟',['تحول تمام محله ثابت شده','بازار قطعاً هیچ اثری ندارد','گزارش افزایش محدود است و تحول کلی اثبات نشده'],'او مشاهدهٔ محدود را از ادعای کلی متمایز می‌کند.',{fr:'un témoignage limité, pas comme une transformation démontrée',de:'als begrenzte Rückmeldung, nicht als nachgewiesene Veränderung des gesamten Viertels',es:'un testimonio limitado, no como una transformación demostrada'})],
 focus:'تیتر، گزارش مشاهده، روش نمونه‌گیری و شواهد مستقل را جداگانه ارزیابی کنید؛ بدون داده نه تأثیر کلی و نه نبود اثر را قطعی کنید.',speaking:'تیتر را با دادهٔ مقاله مقایسه کنید و دو پرسش دربارهٔ منبع مستقل مطرح کنید.',writing:'یادداشت رسانه‌ای کوتاهی با ادعای تیتر، دامنهٔ شاهد و اطلاعات لازم بنویسید.',steps:['ادعای تیتر را نقل کنید.','گروه و زمان مشاهده را دقیق بنویسید.','محدودیت انتخاب و مقایسه را شرح دهید.','منابع مستقل لازم را پیشنهاد کنید.'],
 model:{fr:'Le titre affirme que le marché transforme tout le quartier. Pourtant, l’article ne rapporte que les observations de dix commerçants pendant deux semaines, sans expliquer leur sélection ni comparer d’autres commerces. Il s’agit d’un indice limité, non d’une preuve concernant tous les habitants. Il faudrait consulter des sources indépendantes sur les prix et les effets pour les résidents.',de:'Die Überschrift behauptet, der Markt verändere das ganze Viertel. Der Artikel berichtet jedoch nur über zehn Geschäftsleute während zweier Wochen, ohne deren Auswahl zu erklären oder andere Geschäfte zu vergleichen. Das ist ein begrenzter Hinweis, kein Beweis für Auswirkungen auf alle Bewohner. Unabhängige Daten zu Preisen und Folgen für Anwohner wären nötig.',es:'El titular afirma que el mercado transforma todo el barrio. Sin embargo, el artículo solo recoge las observaciones de diez comerciantes durante dos semanas, sin explicar su selección ni comparar otros comercios. Es un indicio limitado, no una prueba sobre todos los vecinos. Harían falta fuentes independientes sobre los precios y los efectos en los residentes.'}
},
{
 number:15,id:'c1-technology-evidence',title:'بحث مسئولانه دربارهٔ فناوری و داده',
 passage:{fr:'Un hôpital fictif envisage un outil qui classe les demandes de rendez-vous selon leur urgence déclarée. Lors d’une réunion, une ingénieure explique que l’outil ne pose pas de diagnostic et que les résultats devront être vérifiés par du personnel qualifié. Une représentante des patients demande comment le système traitera les personnes qui ne remplissent pas le formulaire en ligne. L’équipe propose de conserver une voie téléphonique et de tester les erreurs sur des données adaptées, sans utiliser de renseignements identifiables. Le projet n’a pas encore été déployé et doit passer un examen de confidentialité et de sécurité.',de:'Ein fiktives Krankenhaus erwägt ein Werkzeug, das Terminanfragen nach der angegebenen Dringlichkeit sortiert. Eine Ingenieurin erklärt in einer Sitzung, dass das Werkzeug keine Diagnose stellt und qualifiziertes Personal die Ergebnisse prüfen muss. Eine Patientenvertreterin fragt, wie Menschen behandelt werden, die das Onlineformular nicht ausfüllen. Das Team schlägt vor, einen telefonischen Zugang beizubehalten und Fehler mit geeigneten Daten ohne identifizierende Angaben zu testen. Das Projekt ist noch nicht eingeführt und muss eine Datenschutz- und Sicherheitsprüfung durchlaufen.',es:'Un hospital ficticio estudia una herramienta que ordena las solicitudes de cita según la urgencia declarada. En una reunión, una ingeniera explica que la herramienta no hace diagnósticos y que personal cualificado debe revisar los resultados. Una representante de pacientes pregunta cómo se atenderá a quienes no rellenan el formulario en línea. El equipo propone mantener una vía telefónica y probar errores con datos adecuados sin información identificable. El proyecto aún no se ha implantado y debe superar una revisión de privacidad y seguridad.'},
 questions:[q('ابزار پیشنهادی چه کاری نمی‌کند؟',['تشخیص پزشکی','مرتب‌کردن درخواست‌ها','استفاده از فوریت اظهارشده'],'ابزار تشخیص نمی‌دهد.',{fr:'l’outil ne pose pas de diagnostic',de:'das Werkzeug keine Diagnose stellt',es:'la herramienta no hace diagnósticos'}),q('برای افرادی که فرم آنلاین پر نمی‌کنند چه گزینه‌ای پیشنهاد شده؟',['حذف راه ارتباطی دیگر','حفظ مسیر تلفنی','تصمیم پزشکی کاملاً خودکار'],'مسیر تلفنی حفظ می‌شود.',{fr:'conserver une voie téléphonique',de:'einen telefonischen Zugang beizubehalten',es:'mantener una vía telefónica'}),q('پیش از استقرار چه بررسی‌ای لازم است؟',['صرفاً تغییر رنگ فرم','انتشار اطلاعات هویتی','بررسی حریم خصوصی و امنیت'],'حریم خصوصی و امنیت باید بررسی شوند.',{fr:'un examen de confidentialité et de sécurité',de:'eine Datenschutz- und Sicherheitsprüfung',es:'una revisión de privacidad y seguridad'})],
 focus:'کارکرد ابزار، محدودیت، نظارت انسانی، دسترسی و ریسک داده را جدا کنید؛ از نسبت دادن تشخیص پزشکی به ابزار پرهیز کنید.',speaking:'برای نمایندهٔ بیماران نقش ابزار، نظارت انسانی و دسترسی تلفنی را توضیح دهید.',writing:'یادداشتی دربارهٔ کاربرد، محدودیت، راه جایگزین و بررسی‌های پیش از اجرا تهیه کنید.',steps:['کارکرد محدود ابزار را معرفی کنید.','نظارت انسانی را مشخص کنید.','راه جایگزین و آزمون خطا را توضیح دهید.','وضعیت بررسی و استقرار را از هم جدا کنید.'],
 model:{fr:'L’outil proposé classerait les demandes selon l’urgence déclarée, sans poser de diagnostic. Le personnel qualifié devra vérifier les résultats. Une voie téléphonique resterait disponible et les erreurs seraient testées sans données identifiables. Le projet n’est pas encore déployé : les questions de confidentialité et de sécurité doivent être examinées avant toute décision.',de:'Das vorgeschlagene Werkzeug würde Anfragen nach angegebener Dringlichkeit sortieren, ohne Diagnosen zu stellen. Qualifiziertes Personal müsste die Ergebnisse prüfen. Ein telefonischer Zugang bliebe bestehen und Fehler würden ohne identifizierende Daten getestet. Das Projekt ist noch nicht eingeführt; Datenschutz und Sicherheit müssen vor einer Entscheidung geprüft werden.',es:'La herramienta propuesta ordenaría las solicitudes según la urgencia declarada, sin realizar diagnósticos. Personal cualificado tendría que revisar los resultados. Se mantendría una vía telefónica y se probarían errores sin datos identificables. El proyecto aún no está implantado: deben examinarse la privacidad y la seguridad antes de decidir.'}
},
{
 number:16,id:'c1-art-criticism',title:'نقد اثر هنری با شاهد و برداشت شخصی',
 passage:{fr:'Dans une exposition fictive, une artiste présente des photographies de fenêtres fermées accompagnées de témoignages audio. Un visiteur y voit une réflexion sur l’isolement ; une autre personne y perçoit surtout une discussion sur la vie privée. La notice indique que l’artiste a recueilli les témoignages avec accord, mais ne précise pas si elle voulait imposer une interprétation unique. Une critique décrit la répétition des fenêtres et les voix sans attribuer automatiquement une intention à l’artiste. Elle compare ensuite les deux lectures et explique pourquoi elles lui semblent possibles, tout en reconnaissant les limites de sa propre interprétation.',de:'In einer fiktiven Ausstellung zeigt eine Künstlerin Fotografien geschlossener Fenster mit aufgezeichneten Stimmen. Ein Besucher sieht darin eine Reflexion über Einsamkeit; eine andere Person erkennt vor allem eine Auseinandersetzung mit Privatsphäre. Der Ausstellungstext sagt, dass die Stimmen mit Einwilligung aufgenommen wurden, aber nicht, dass die Künstlerin eine einzige Deutung vorgeben wollte. Eine Kritikerin beschreibt die wiederholten Fenster und die Stimmen, ohne der Künstlerin automatisch eine Absicht zuzuschreiben. Danach vergleicht sie beide Lesarten und erläutert ihre eigene Deutung samt deren Grenzen.',es:'En una exposición ficticia, una artista presenta fotografías de ventanas cerradas acompañadas de testimonios sonoros. Un visitante ve una reflexión sobre el aislamiento; otra persona percibe sobre todo una discusión sobre la privacidad. El texto de sala indica que la artista recogió los testimonios con consentimiento, pero no dice que quisiera imponer una interpretación única. Una crítica describe la repetición de las ventanas y las voces sin atribuir automáticamente una intención a la artista. Después compara las dos lecturas y explica por qué le parecen posibles, reconociendo los límites de su propia interpretación.'},
 questions:[q('دو برداشت بازدیدکنندگان چیست؟',['انزوا و حریم خصوصی','قیمت بلیت و ساعت افتتاح','فقط نیت قطعی هنرمند'],'برداشت‌ها به انزوا و حریم خصوصی مربوط‌اند.',{fr:'une réflexion sur l’isolement ; une autre personne y perçoit surtout une discussion sur la vie privée',de:'eine Reflexion über Einsamkeit; eine andere Person erkennt vor allem eine Auseinandersetzung mit Privatsphäre',es:'una reflexión sobre el aislamiento; otra persona percibe sobre todo una discusión sobre la privacidad'}),q('متن نمایشگاه دربارهٔ نیت تفسیری چه نمی‌گوید؟',['اینکه صدا ضبط شده','اینکه هنرمند تفسیر واحدی را تحمیل می‌خواست','اینکه عکس وجود دارد'],'نیت تحمیل یک تفسیر در متن تأیید نشده است.',{fr:'ne précise pas si elle voulait imposer une interprétation unique',de:'nicht, dass die Künstlerin eine einzige Deutung vorgeben wollte',es:'no dice que quisiera imponer una interpretación única'}),q('منتقد چگونه عمل می‌کند؟',['نیت هنرمند را بدون شاهد قطعی می‌داند','همهٔ برداشت‌ها را حذف می‌کند','مشاهده و تفسیر را جدا و دو خوانش را مقایسه می‌کند'],'منتقد عناصر اثر و برداشت‌ها را با احتیاط بررسی می‌کند.',{fr:'décrit la répétition des fenêtres et les voix sans attribuer automatiquement une intention',de:'beschreibt die wiederholten Fenster und die Stimmen, ohne der Künstlerin automatisch eine Absicht zuzuschreiben',es:'describe la repetición de las ventanas y las voces sin atribuir automáticamente una intención'})],
 focus:'در نقد هنری عنصر قابل مشاهده، برداشت شخصی و قصد اثبات‌شدهٔ خالق را تفکیک کنید؛ چند خوانش می‌توانند هم‌زمان قابل دفاع باشند.',speaking:'دو برداشت را با ارجاع به عناصر اثر مقایسه کنید و محدودیت تفسیر خود را بگویید.',writing:'نقدی کوتاه با توصیف، دو تفسیر و یک قید دربارهٔ قصد هنرمند بنویسید.',steps:['عناصر اثر را توصیف کنید.','دو خوانش متفاوت را مطرح کنید.','شاهد هر برداشت را توضیح دهید.','قصد هنرمند را بدون مدرک قطعی ندانید.'],
 model:{fr:'L’exposition associe des fenêtres fermées à des voix enregistrées avec accord. Leur répétition peut évoquer l’isolement, mais elle peut aussi inviter à réfléchir à la vie privée. Je trouve la première lecture convaincante en raison du contraste entre fermeture et voix. Toutefois, la notice ne confirme pas que l’artiste voulait imposer cette interprétation ; d’autres lectures restent possibles.',de:'Die Ausstellung verbindet geschlossene Fenster mit Stimmen, die mit Einwilligung aufgenommen wurden. Die Wiederholung kann Einsamkeit vermitteln, aber auch Fragen der Privatsphäre aufwerfen. Ich finde die erste Lesart wegen des Kontrasts zwischen geschlossenen Fenstern und Stimmen überzeugend. Der Ausstellungstext bestätigt jedoch nicht, dass die Künstlerin diese Deutung vorgeben wollte; andere Lesarten bleiben möglich.',es:'La exposición combina ventanas cerradas con voces grabadas con consentimiento. La repetición puede evocar el aislamiento, pero también plantear cuestiones sobre la privacidad. La primera lectura me parece convincente por el contraste entre cierre y voces. Sin embargo, el texto de sala no confirma que la artista quisiera imponer esa interpretación; otras lecturas siguen siendo posibles.'}
},
{
 number:17,id:'c1-academic-discussion',title:'گفت‌وگوی پژوهشی دربارهٔ روش نمونه‌گیری',
 passage:{fr:'Lors d’un séminaire fictif, une doctorante présente une étude sur les trajets domicile-travail. Elle a interrogé quinze volontaires recrutés près d’une gare et observe que plusieurs combinent train et vélo. Un chercheur demande si ce recrutement exclut les personnes qui n’utilisent pas la gare. Elle reconnaît cette limite et explique que l’étude explore des expériences, sans estimer une proportion pour toute la ville. Une collègue suggère de recruter aussi dans d’autres quartiers et à différentes heures. La doctorante accepte d’étudier cette possibilité avant de modifier son protocole.',de:'In einem fiktiven Seminar stellt eine Doktorandin eine Studie zu Arbeitswegen vor. Sie befragte fünfzehn Freiwillige, die nahe einem Bahnhof gewonnen wurden, und beobachtet, dass mehrere Zug und Fahrrad kombinieren. Ein Forscher fragt, ob diese Auswahl Menschen ausschließt, die den Bahnhof nicht nutzen. Sie erkennt die Grenze an und erklärt, dass die Studie Erfahrungen erkundet, ohne einen Anteil für die ganze Stadt zu schätzen. Eine Kollegin schlägt eine Rekrutierung in anderen Vierteln und zu verschiedenen Zeiten vor. Die Doktorandin prüft dies, bevor sie ihr Protokoll ändert.',es:'En un seminario ficticio, una doctoranda presenta un estudio sobre desplazamientos al trabajo. Entrevistó a quince voluntarios reclutados cerca de una estación y observa que varios combinan tren y bicicleta. Un investigador pregunta si esta selección excluye a quienes no usan la estación. Ella reconoce el límite y explica que el estudio explora experiencias sin estimar una proporción para toda la ciudad. Una compañera sugiere reclutar también en otros barrios y a distintas horas. La doctoranda acepta estudiar la posibilidad antes de modificar su protocolo.'},
 questions:[q('شرکت‌کنندگان کجا جذب شدند؟',['نزدیک ایستگاه','در همهٔ مناطق به‌طور تصادفی','در یک بیمارستان'],'داوطلبان نزدیک ایستگاه جذب شدند.',{fr:'recrutés près d’une gare',de:'nahe einem Bahnhof gewonnen',es:'reclutados cerca de una estación'}),q('هدف ادعایی مطالعه چیست؟',['برآورد دقیق کل شهر','کاوش تجربه‌ها، نه تخمین نسبت کل شهر','اثبات قطعی علت سفر'],'مطالعه تجربه‌ها را بررسی می‌کند نه نسبت کل شهر را.',{fr:'l’étude explore des expériences, sans estimer une proportion pour toute la ville',de:'die Studie Erfahrungen erkundet, ohne einen Anteil für die ganze Stadt zu schätzen',es:'el estudio explora experiencias sin estimar una proporción para toda la ciudad'}),q('پیشنهاد همکار دربارهٔ نمونه چیست؟',['حذف همهٔ مصاحبه‌ها','انتشار نتیجه بدون محدودیت','جذب در محله‌ها و ساعت‌های متنوع'],'او مکان‌ها و زمان‌های دیگر را پیشنهاد می‌کند.',{fr:'recruter aussi dans d’autres quartiers et à différentes heures',de:'eine Rekrutierung in anderen Vierteln und zu verschiedenen Zeiten',es:'reclutar también en otros barrios y a distintas horas'})],
 focus:'در بحث پژوهشی پرسش روش، محدودیت نمونه و دامنهٔ ادعا را جدا کنید؛ پذیرش بررسی پیشنهاد با تغییر قطعی روش یکی نیست.',speaking:'در نقش پژوهشگر به پرسش نمونه‌گیری پاسخ دهید و محدودهٔ نتیجه را روشن کنید.',writing:'پاسخی دانشگاهی با روش، محدودیت و امکان اصلاح روش بنویسید.',steps:['روش جذب و تعداد را بیان کنید.','خطر حذف غیرکاربران ایستگاه را توضیح دهید.','دامنهٔ محدود مطالعه را روشن کنید.','پیشنهاد همکار را بدون ادعای تصویب قطعی ثبت کنید.'],
 model:{fr:'Nous avons interrogé quinze volontaires recrutés près de la gare. Cette méthode peut exclure les personnes qui ne l’utilisent pas ; nos résultats explorent donc des expériences et ne permettent pas d’estimer une proportion pour la ville. La proposition de recruter dans d’autres quartiers et à différentes heures mérite d’être examinée avant toute modification du protocole.',de:'Wir haben fünfzehn Freiwillige nahe dem Bahnhof befragt. Dadurch können Menschen ausgeschlossen sein, die ihn nicht nutzen; unsere Ergebnisse erkunden Erfahrungen und erlauben keine Schätzung für die ganze Stadt. Den Vorschlag, in anderen Vierteln und zu verschiedenen Zeiten zu rekrutieren, sollten wir vor einer Änderung des Protokolls prüfen.',es:'Entrevistamos a quince voluntarios reclutados cerca de la estación. Este método puede excluir a quienes no la usan; los resultados exploran experiencias y no permiten estimar una proporción para la ciudad. Conviene examinar la propuesta de reclutar en otros barrios y a distintas horas antes de modificar el protocolo.'}
},
{
 number:18,id:'c1-hypothesis-evaluation',title:'ساخت و سنجش فرضیهٔ پژوهشی',
 passage:{fr:'Une équipe remarque que moins de personnes utilisent une salle d’étude le vendredi. Elle formule l’hypothèse que les horaires de transport jouent un rôle, mais reconnaît que les cours, le travail et les examens pourraient aussi influencer les visites. Le relevé actuel ne contient ni horaires individuels ni raisons d’absence. Pour vérifier l’hypothèse, elle propose de comparer plusieurs vendredis et de demander anonymement quels obstacles les usagers rencontrent. Une réponse favorable à l’hypothèse ne suffirait pas, à elle seule, à prouver une cause. Le protocole doit encore être examiné.',de:'Ein Team bemerkt, dass am Freitag weniger Menschen einen Lernraum nutzen. Es formuliert die Hypothese, dass Verkehrszeiten eine Rolle spielen, erkennt aber an, dass auch Unterricht, Arbeit und Prüfungen die Besuche beeinflussen könnten. Die vorhandene Erfassung enthält weder individuelle Zeiten noch Gründe für Abwesenheit. Zur Prüfung schlägt es vor, mehrere Freitage zu vergleichen und Nutzer anonym nach Hindernissen zu fragen. Ein zur Hypothese passendes Ergebnis würde allein noch keine Ursache beweisen. Das Protokoll muss noch geprüft werden.',es:'Un equipo observa que menos personas usan una sala de estudio los viernes. Formula la hipótesis de que los horarios de transporte influyen, pero reconoce que las clases, el trabajo y los exámenes también podrían afectar a las visitas. El registro actual no contiene horarios individuales ni motivos de ausencia. Para examinar la hipótesis propone comparar varios viernes y preguntar de forma anónima qué obstáculos encuentran los usuarios. Un resultado favorable a la hipótesis no bastaría por sí solo para demostrar una causa. El protocolo aún debe revisarse.'},
 questions:[q('فرضیهٔ گروه به چه مربوط است؟',['نقش احتمالی زمان حمل‌ونقل','تأیید قطعی علت غیبت','حذف سالن در جمعه'],'گروه نقش احتمالی حمل‌ونقل را فرض می‌کند.',{fr:'les horaires de transport jouent un rôle',de:'Verkehrszeiten eine Rolle spielen',es:'los horarios de transporte influyen'}),q('در دادهٔ موجود چه چیزی نیست؟',['وجود سالن','زمان فردی و دلیل غیبت','وجود روز جمعه'],'دادهٔ فردی و علت غیبت ثبت نشده‌اند.',{fr:'ni horaires individuels ni raisons d’absence',de:'weder individuelle Zeiten noch Gründe für Abwesenheit',es:'no contiene horarios individuales ni motivos de ausencia'}),q('آیا نتیجهٔ موافق فرضیه به‌تنهایی علت را ثابت می‌کند؟',['بله همیشه','فقط با یک مشاهده','خیر، به‌تنهایی کافی نیست'],'نتیجهٔ موافق به‌تنهایی علت را ثابت نمی‌کند.',{fr:'ne suffirait pas, à elle seule, à prouver une cause',de:'würde allein noch keine Ursache beweisen',es:'no bastaría por sí solo para demostrar una causa'})],
 focus:'فرضیه، پیش‌بینی، دادهٔ لازم و توضیح جایگزین را تفکیک کنید؛ همخوانی با فرضیه به‌تنهایی اثبات علت نیست.',speaking:'فرضیه، عوامل جایگزین و روش پیشنهادی سنجش را برای همکار توضیح دهید.',writing:'طرح کوتاهی برای ارزیابی فرضیه با محدودیت‌های استنباط بنویسید.',steps:['مشاهده و فرضیه را جدا کنید.','دو عامل جایگزین نام ببرید.','مقایسه و پرسش ناشناس را شرح دهید.','حدود نتیجهٔ احتمالی را مشخص کنید.'],
 model:{fr:'La baisse des visites le vendredi pourrait être liée aux transports, mais d’autres facteurs, comme les cours ou le travail, sont possibles. Le relevé actuel ne contient pas les raisons d’absence. Comparer plusieurs vendredis et interroger anonymement les usagers aiderait à explorer l’hypothèse. Même un résultat favorable ne prouverait pas à lui seul une relation causale ; le protocole reste à examiner.',de:'Die geringere Nutzung am Freitag könnte mit dem Verkehr zusammenhängen, aber auch Unterricht oder Arbeit können eine Rolle spielen. Die Gründe für Abwesenheit sind nicht erfasst. Ein Vergleich mehrerer Freitage und eine anonyme Befragung könnten die Hypothese untersuchen. Selbst ein passendes Ergebnis würde allein keine Kausalität beweisen; das Protokoll muss noch geprüft werden.',es:'La menor asistencia los viernes podría relacionarse con el transporte, aunque también pueden influir las clases o el trabajo. No se han registrado los motivos de ausencia. Comparar varios viernes y preguntar anónimamente a los usuarios ayudaría a examinar la hipótesis. Incluso un resultado favorable no demostraría por sí solo causalidad; el protocolo debe revisarse.'}
},
{
 number:19,id:'c1-explain-specialty',title:'توضیح مفهوم تخصصی برای غیرمتخصص',
 passage:{fr:'Une ingénieure doit expliquer le chiffrement à des bénévoles sans formation informatique. Elle compare une clé numérique à un moyen de rendre un message illisible aux personnes qui ne disposent pas de l’accès prévu. Elle précise que l’analogie est limitée : un système réel dépend aussi de la gestion des clés et des appareils. Un bénévole demande si le chiffrement empêche toutes les erreurs humaines. Elle répond que non et recommande de vérifier les destinataires avant l’envoi. Elle évite les détails mathématiques inutiles, puis demande au groupe de reformuler l’idée et de poser des questions.',de:'Eine Ingenieurin erklärt Ehrenamtlichen ohne Informatikausbildung die Verschlüsselung. Sie vergleicht einen digitalen Schlüssel mit einem Mittel, eine Nachricht für Personen ohne vorgesehenen Zugang unlesbar zu machen. Sie betont die Grenzen des Vergleichs: Ein reales System hängt auch von der Verwaltung der Schlüssel und Geräte ab. Ein Freiwilliger fragt, ob Verschlüsselung alle menschlichen Fehler verhindert. Sie verneint und empfiehlt, vor dem Senden die Empfänger zu prüfen. Sie vermeidet unnötige mathematische Details und bittet die Gruppe, die Idee in eigenen Worten wiederzugeben und Fragen zu stellen.',es:'Una ingeniera explica el cifrado a voluntarios sin formación informática. Compara una clave digital con un medio para hacer ilegible un mensaje a quienes no tienen el acceso previsto. Precisa que la analogía es limitada: un sistema real también depende de la gestión de claves y dispositivos. Un voluntario pregunta si el cifrado evita todos los errores humanos. Ella responde que no y recomienda comprobar los destinatarios antes de enviar. Evita detalles matemáticos innecesarios y pide al grupo que reformule la idea y haga preguntas.'},
 questions:[q('هدف تشبیه چیست؟',['توضیح مفهوم به افراد غیرمتخصص','اثبات اینکه امنیت مطلق است','جایگزینی مدیریت دستگاه'],'تشبیه به فهم یک ایده برای غیرمتخصصان کمک می‌کند.',{fr:'sans formation informatique',de:'ohne Informatikausbildung',es:'sin formación informática'}),q('محدودیت تشبیه چیست؟',['همهٔ جزئیات سامانه را پوشش می‌دهد','سامانه به مدیریت کلید و دستگاه نیز وابسته است','هیچ کلیدی در سامانه وجود ندارد'],'سامانهٔ واقعی به مدیریت کلید و دستگاه وابسته است.',{fr:'la gestion des clés et des appareils',de:'der Verwaltung der Schlüssel und Geräte',es:'la gestión de claves y dispositivos'}),q('آیا رمزگذاری همهٔ خطاهای انسانی را رفع می‌کند؟',['بله، به‌طور قطعی','فقط در ایمیل','خیر، بررسی گیرنده همچنان مهم است'],'او پاسخ منفی می‌دهد و بررسی گیرنده را توصیه می‌کند.',{fr:'Elle répond que non et recommande de vérifier les destinataires',de:'Sie verneint und empfiehlt, vor dem Senden die Empfänger zu prüfen',es:'Ella responde que no y recomienda comprobar los destinatarios'})],
 focus:'با زبان ساده و تشبیه توضیح دهید، اما مرز تشبیه و محدودیت راهکار را مشخص کنید؛ از وعدهٔ امنیت مطلق بپرهیزید.',speaking:'رمزگذاری را با تشبیه و یک محدودیت برای داوطلب توضیح دهید و از او بخواهید برداشتش را بازگو کند.',writing:'توضیحی کوتاه برای غیرمتخصص با مثال، محدودیت و یک اقدام احتیاطی بنویسید.',steps:['مفهوم را بدون اصطلاح غیرضروری معرفی کنید.','یک تشبیه قابل فهم ارائه دهید.','محدودیت تشبیه را بگویید.','اقدام احتیاطی و پرسش باز اضافه کنید.'],
 model:{fr:'Le chiffrement aide à rendre un message illisible pour une personne qui ne dispose pas de l’accès prévu. On peut penser à une clé, mais cette comparaison ne décrit pas tout : la gestion des clés et des appareils compte aussi. Le chiffrement ne supprime pas toutes les erreurs humaines ; vérifiez les destinataires avant l’envoi. Comment expliqueriez-vous cette idée ?',de:'Verschlüsselung hilft, eine Nachricht für Personen ohne vorgesehenen Zugang unlesbar zu machen. Ein Schlüssel ist ein nützlicher Vergleich, erklärt aber nicht alles: Auch die Verwaltung von Schlüsseln und Geräten ist wichtig. Verschlüsselung verhindert nicht alle menschlichen Fehler; prüfen Sie vor dem Senden die Empfänger. Wie würden Sie die Idee erklären?',es:'El cifrado ayuda a que un mensaje sea ilegible para quien no tiene el acceso previsto. Una llave es una comparación útil, pero no explica todo: también importa gestionar las claves y los dispositivos. El cifrado no elimina todos los errores humanos; comprueben los destinatarios antes de enviar. ¿Cómo explicarían esta idea?'}
},
{
 number:20,id:'c1-complex-qa',title:'مدیریت پرسش‌های چندبخشی',
 passage:{fr:'Après une présentation sur un centre sportif, une participante pose deux questions : combien coûtera l’ouverture tardive et comment les employés seront consultés. La responsable connaît une estimation du coût de l’électricité, mais pas encore celle du personnel. Elle répète les deux parties de la question, communique le montant disponible sans le présenter comme le coût total, puis explique qu’une consultation est prévue. Elle promet de transmettre le coût complet après vérification et demande si la réponse couvre bien les deux points. Aucune date définitive d’ouverture n’a été fixée.',de:'Nach einer Präsentation über ein Sportzentrum stellt eine Teilnehmerin zwei Fragen: Was kostet die spätere Öffnung und wie werden die Beschäftigten befragt? Die Verantwortliche kennt eine Schätzung der Stromkosten, aber noch nicht die Personalkosten. Sie wiederholt beide Teile der Frage, nennt den verfügbaren Betrag, ohne ihn als Gesamtkosten darzustellen, und erklärt die geplante Befragung. Nach Prüfung will sie die Gesamtkosten mitteilen und fragt, ob beide Punkte beantwortet sind. Ein endgültiger Öffnungstermin steht nicht fest.',es:'Después de una presentación sobre un centro deportivo, una participante plantea dos preguntas: cuánto costará abrir más tarde y cómo se consultará a los empleados. La responsable conoce una estimación del coste eléctrico, pero todavía no el coste de personal. Repite las dos partes, comunica la cifra disponible sin presentarla como coste total y explica que está prevista una consulta. Promete comunicar el coste completo después de comprobarlo y pregunta si ha respondido a ambos puntos. No se ha fijado una fecha definitiva de apertura.'},
 questions:[q('پرسش دو بخش آن چیست؟',['هزینه و شیوهٔ مشورت کارکنان','رنگ دیوار و قیمت بلیت قطار','نام دو بازیکن'],'پرسش دربارهٔ هزینه و مشورت کارکنان است.',{fr:'combien coûtera l’ouverture tardive et comment les employés seront consultés',de:'Was kostet die spätere Öffnung und wie werden die Beschäftigten befragt',es:'cuánto costará abrir más tarde y cómo se consultará a los empleados'}),q('چه بخشی از هزینه هنوز معلوم نیست؟',['برآورد برق','هزینهٔ کارکنان','وجود مرکز'],'هزینهٔ نیروی انسانی هنوز معلوم نیست.',{fr:'pas encore celle du personnel',de:'noch nicht die Personalkosten',es:'todavía no el coste de personal'}),q('مسئول چگونه از کامل‌بودن پاسخ مطمئن می‌شود؟',['سؤال را نادیده می‌گیرد','هزینهٔ برق را کل هزینه می‌نامد','می‌پرسد آیا به هر دو بخش پاسخ داده است'],'او دربارهٔ پوشش هر دو بخش سؤال می‌کند.',{fr:'demande si la réponse couvre bien les deux points',de:'fragt, ob beide Punkte beantwortet sind',es:'pregunta si ha respondido a ambos puntos'})],
 focus:'پرسش چندبخشی را بازگو و دسته‌بندی کنید، معلوم و نامعلوم را جدا کنید و برای پاسخ ناقص پیگیری مشخص بدهید.',speaking:'دو بخش پرسش را تکرار و به هر کدام با اطلاعات موجود و پیگیری پاسخ دهید.',writing:'پاسخی ساختاریافته دربارهٔ هزینه و مشورت بنویسید و رقم ناقص را کل هزینه ننامید.',steps:['دو بخش را بازگو کنید.','هزینهٔ شناخته‌شده و نامعلوم را جدا کنید.','برنامهٔ مشورت را ذکر کنید.','تعهد پیگیری و تأیید فهم را اضافه کنید.'],
 model:{fr:'Vous demandez le coût de l’ouverture et la façon de consulter les employés. Nous disposons d’une estimation de l’électricité, mais pas encore du personnel ; ce n’est donc pas un coût total. Une consultation est prévue et nous transmettrons le montant complet après vérification. Ai-je bien répondu aux deux points ? La date d’ouverture reste à déterminer.',de:'Sie fragen nach den Kosten der Öffnung und der Befragung der Beschäftigten. Eine Schätzung der Stromkosten liegt vor, die Personalkosten fehlen noch; es handelt sich also nicht um Gesamtkosten. Eine Befragung ist geplant und den Gesamtbetrag teilen wir nach Prüfung mit. Habe ich beide Punkte beantwortet? Der Öffnungstermin steht noch nicht fest.',es:'Pregunta por el coste de la apertura y por la consulta a los empleados. Disponemos de una estimación eléctrica, pero aún falta el coste de personal; por tanto no es el coste total. Hay una consulta prevista y comunicaremos la cifra completa tras comprobarla. ¿He respondido a ambos puntos? La fecha sigue sin fijarse.'}
},
{
 number:21,id:'c1-register-shift',title:'تنظیم لحن برای مخاطبان متفاوت',
 passage:{fr:'Une association doit informer ses partenaires qu’un atelier est reporté, sans nouvelle date confirmée. Pour la mairie, elle prépare une lettre formelle qui explique le report et propose un point de suivi. Pour les bénévoles, elle rédige un message professionnel précisant les tâches suspendues. Une organisatrice informe aussi une amie dans un style familier. Elle conserve les mêmes faits dans les trois messages et ne partage aucune donnée personnelle. Un collègue vérifie que la formule amicale ne suggère pas une date déjà décidée et que la lettre officielle ne promet pas une décision de la mairie.',de:'Ein Verein muss seine Partner darüber informieren, dass ein Workshop verschoben wird und kein neuer Termin bestätigt ist. Für die Stadtverwaltung verfasst er ein formelles Schreiben mit einer Erklärung und einem Vorschlag zur Rückmeldung. Für die Freiwilligen schreibt er eine berufliche Nachricht über die ausgesetzten Aufgaben. Eine Organisatorin informiert auch eine Freundin in vertrauter Sprache. In allen drei Nachrichten bleiben die Tatsachen gleich und persönliche Daten werden nicht weitergegeben. Ein Kollege prüft, dass weder ein entschiedener Termin noch eine Entscheidung der Verwaltung vorgetäuscht wird.',es:'Una asociación debe informar a sus socios de que un taller se aplaza sin nueva fecha confirmada. Para el ayuntamiento prepara una carta formal que explica el aplazamiento y propone un seguimiento. Para los voluntarios redacta un mensaje profesional que precisa las tareas suspendidas. Una organizadora informa también a una amiga en un estilo cercano. Mantiene los mismos hechos en los tres mensajes y no comparte datos personales. Un compañero comprueba que el mensaje amistoso no sugiera una fecha ya decidida y que la carta no prometa una decisión del ayuntamiento.'},
 questions:[q('وضعیت تاریخ کارگاه چیست؟',['تاریخ جدید تأیید نشده است','دوشنبه قطعاً برگزار می‌شود','برای همیشه لغو شده است'],'کارگاه تعویق یافته و تاریخ جدید تأیید نشده است.',{fr:'sans nouvelle date confirmée',de:'kein neuer Termin bestätigt ist',es:'sin nueva fecha confirmada'}),q('در هر سه پیام چه چیزی باید ثابت بماند؟',['فقط طول جمله‌ها','واقعیت و محرمانگی','رسمیت یکسان'],'واقعیت و اطلاعات شخصی در هر سه پیام حفظ می‌شوند.',{fr:'les mêmes faits dans les trois messages et ne partage aucune donnée personnelle',de:'bleiben die Tatsachen gleich und persönliche Daten werden nicht weitergegeben',es:'los mismos hechos en los tres mensajes y no comparte datos personales'}),q('همکار چه موردی را بررسی می‌کند؟',['حذف همهٔ اطلاعات مربوط به تعویق','اعلام تصمیم قطعی شهرداری','پرهیز از القای تاریخ یا تصمیم تأییدنشده'],'او از القای تصمیم یا تاریخ قطعی جلوگیری می‌کند.',{fr:'ne suggère pas une date déjà décidée',de:'weder ein entschiedener Termin noch eine Entscheidung der Verwaltung vorgetäuscht wird',es:'no sugiera una fecha ya decidida'})],
 focus:'رسمیت، مخاطب و هدف را تغییر دهید، ولی واقعیت، قطعیت و محرمانگی را ثابت نگه دارید.',speaking:'تعویق را یک بار به نمایندهٔ شهرداری و یک بار به دوست توضیح دهید.',writing:'یک پیام رسمی و یک پیام دوستانه بنویسید که وضعیت واقعی را تغییر ندهند.',steps:['مخاطب و هدف را شناسایی کنید.','نسخهٔ رسمی و گام پیگیری بنویسید.','نسخهٔ دوستانه را بازگو کنید.','قطعیت و محرمانگی هر دو را بررسی کنید.'],
 model:{fr:'À la mairie : Nous vous informons que l’atelier est reporté ; aucune nouvelle date n’est confirmée. Nous proposons de faire un point la semaine prochaine. À une amie : L’atelier est repoussé et on ne connaît pas encore la nouvelle date. Je te tiendrai au courant quand elle sera confirmée. Dans les deux messages, aucune décision de la mairie n’est supposée.',de:'An die Stadtverwaltung: Wir teilen Ihnen mit, dass der Workshop verschoben wird; ein neuer Termin ist nicht bestätigt. Wir schlagen eine Rückmeldung nächste Woche vor. An eine Freundin: Der Workshop ist verschoben und wir kennen den neuen Termin noch nicht. Ich sage dir Bescheid, sobald er bestätigt ist. Eine Entscheidung der Verwaltung wird nicht vorausgesetzt.',es:'Al ayuntamiento: Les informamos de que el taller se aplaza y no hay una nueva fecha confirmada. Proponemos hacer un seguimiento la próxima semana. A una amiga: El taller se ha aplazado y todavía no sabemos la nueva fecha. Te avisaré cuando se confirme. En ninguno de los mensajes se presupone una decisión del ayuntamiento.'}
},
{
 number:22,id:'c1-humor-irony',title:'طنز و کنایه در بافت حرفه‌ای',
 passage:{fr:'Au terme d’une réunion qui a duré deux heures de plus que prévu, une collègue dit en souriant : « Voilà une réunion très courte ! » Plusieurs personnes comprennent son ironie, mais un nouveau participant croit qu’elle est sérieuse. Le responsable reformule sans lui attribuer une intention hostile : la réunion a été plus longue que prévu et il faut clarifier la suite. Pour le compte rendu officiel, il évite la plaisanterie et indique les horaires réels. La collègue confirme qu’elle voulait signaler le dépassement avec humour, non critiquer une personne.',de:'Nach einer Sitzung, die zwei Stunden länger als geplant dauerte, sagt eine Kollegin lächelnd: „Das war aber eine sehr kurze Sitzung!“ Einige verstehen die Ironie, ein neuer Teilnehmer nimmt sie jedoch wörtlich. Der Verantwortliche formuliert um, ohne ihr eine feindliche Absicht zu unterstellen: Die Sitzung war länger als geplant und das weitere Vorgehen muss geklärt werden. Im offiziellen Protokoll verzichtet er auf den Scherz und nennt die tatsächlichen Zeiten. Die Kollegin bestätigt, dass sie humorvoll auf die Überschreitung hinweisen und keine Person kritisieren wollte.',es:'Al terminar una reunión que duró dos horas más de lo previsto, una compañera dice sonriendo: «¡Qué reunión tan corta!». Varias personas entienden la ironía, pero un participante nuevo cree que habla en serio. El responsable reformula sin atribuirle una intención hostil: la reunión duró más de lo previsto y hay que aclarar los siguientes pasos. En el acta oficial evita la broma e indica los horarios reales. La compañera confirma que quería señalar el exceso con humor, no criticar a una persona.'},
 questions:[q('کنایه به کدام واقعیت اشاره می‌کند؟',['جلسه دو ساعت بیش از برنامه طول کشید','جلسه اصلاً برگزار نشد','جلسه زودتر تمام شد'],'جلسه دو ساعت بیشتر طول کشید.',{fr:'deux heures de plus que prévu',de:'zwei Stunden länger als geplant',es:'dos horas más de lo previsto'}),q('چرا مسئول بازنویسی می‌کند؟',['برای تشدید اتهام شخصی','برای روشن‌کردن واقعیت و گام بعد بدون نسبت‌دادن نیت خصمانه','برای پنهان‌کردن مدت واقعی'],'او واقعیت و گام بعدی را بدون نسبت دادن نیت خصمانه روشن می‌کند.',{fr:'reformule sans lui attribuer une intention hostile',de:'formuliert um, ohne ihr eine feindliche Absicht zu unterstellen',es:'reformula sin atribuirle una intención hostil'}),q('در صورت‌جلسه چه می‌آید؟',['همان کنایه بدون توضیح','اتهام قطعی به همکار','ساعت‌های واقعی به جای شوخی'],'صورت‌جلسه ساعت‌های واقعی را ثبت می‌کند.',{fr:'évite la plaisanterie et indique les horaires réels',de:'verzichtet er auf den Scherz und nennt die tatsächlichen Zeiten',es:'evita la broma e indica los horarios reales'})],
 focus:'کنایه به بافت و مخاطب وابسته است؛ در سند رسمی واقعیت را روشن و از نسبت دادن نیت بدون شاهد پرهیز کنید.',speaking:'کنایه را برای فرد تازه‌وارد روشن کنید و گام بعد را بی‌اتهام بیان کنید.',writing:'یک صورت‌جلسهٔ رسمی و یک توضیح دوستانه دربارهٔ طول جلسه بنویسید.',steps:['عبارت و واقعیت را جدا کنید.','احتمال سوءبرداشت را توضیح دهید.','ساعت‌های واقعی را در متن رسمی ثبت کنید.','قصد گوینده را بدون تأیید قطعی فرض نکنید.'],
 model:{fr:'La remarque était ironique : la réunion a en réalité duré deux heures de plus que prévu. Dans le compte rendu, nous indiquerons les horaires réels et les prochaines actions, sans reprendre la plaisanterie. La collègue a confirmé qu’elle voulait signaler le dépassement avec humour, pas critiquer quelqu’un. Vérifions maintenant les points qui restent ouverts.',de:'Die Bemerkung war ironisch: Die Sitzung dauerte tatsächlich zwei Stunden länger als geplant. Im Protokoll nennen wir die tatsächlichen Zeiten und nächsten Schritte, ohne den Scherz zu wiederholen. Die Kollegin bestätigte, dass sie die Überschreitung humorvoll ansprechen und niemanden kritisieren wollte. Prüfen wir nun die offenen Punkte.',es:'La observación era irónica: la reunión duró en realidad dos horas más de lo previsto. En el acta indicaremos los horarios reales y los próximos pasos, sin repetir la broma. La compañera confirmó que quería señalar el exceso con humor y no criticar a nadie. Revisemos ahora los puntos pendientes.'}
},
{
 number:23,id:'c1-intercultural-communication',title:'رفع سوءبرداشت بین‌فرهنگی بدون کلیشه',
 passage:{fr:'Deux partenaires de pays différents préparent une réunion en ligne. L’un envoie un ordre du jour très détaillé ; l’autre répond seulement qu’il est « à revoir ». Le premier pense que tout le programme est rejeté, mais il demande une précision avant de conclure. Sa partenaire explique qu’elle souhaite surtout modifier la durée de deux points et qu’elle approuve l’objectif général. Ils conviennent de préciser par écrit les éléments approuvés et ouverts. Ils évitent d’attribuer le malentendu à une caractéristique de toute une culture et vérifient plutôt leurs attentes individuelles.',de:'Zwei Partner aus verschiedenen Ländern bereiten eine Onlinebesprechung vor. Einer schickt eine sehr ausführliche Tagesordnung; die andere antwortet nur, sie müsse „überarbeitet werden“. Der erste glaubt, das gesamte Programm werde abgelehnt, fragt aber vor einer Schlussfolgerung nach. Seine Partnerin erklärt, dass sie vor allem die Dauer zweier Punkte ändern möchte und das Gesamtziel unterstützt. Sie vereinbaren, angenommene und offene Punkte schriftlich zu präzisieren. Statt das Missverständnis einer ganzen Kultur zuzuschreiben, klären sie ihre individuellen Erwartungen.',es:'Dos socios de países distintos preparan una reunión en línea. Uno envía un orden del día muy detallado; la otra responde solo que «hay que revisarlo». El primero piensa que se rechaza todo el programa, pero pide una aclaración antes de concluir. Su socia explica que desea sobre todo modificar la duración de dos puntos y que apoya el objetivo general. Acuerdan precisar por escrito lo aceptado y lo pendiente. Evitan atribuir el malentendido a una característica de toda una cultura y comprueban sus expectativas individuales.'},
 questions:[q('برداشت اولیهٔ شریک نخست چه بود؟',['رد کل برنامه','پذیرش قطعی همهٔ جزئیات','لغو همکاری برای همیشه'],'او ابتدا تصور می‌کند کل برنامه رد شده است.',{fr:'tout le programme est rejeté',de:'das gesamte Programm werde abgelehnt',es:'se rechaza todo el programa'}),q('طرف مقابل واقعاً چه تغییری می‌خواهد؟',['حذف هدف کلی','اصلاح زمان دو بخش با پذیرش هدف کلی','حذف جلسه بدون دلیل'],'او هدف را می‌پذیرد و می‌خواهد مدت دو بخش اصلاح شود.',{fr:'modifier la durée de deux points et qu’elle approuve l’objectif général',de:'die Dauer zweier Punkte ändern möchte und das Gesamtziel unterstützt',es:'modificar la duración de dos puntos y que apoya el objetivo general'}),q('از چه رویکردی پرهیز می‌کنند؟',['شفاف‌سازی کتبی','پرسیدن دربارهٔ انتظار افراد','تعمیم سوءبرداشت به کل یک فرهنگ'],'آنها به جای کلیشه انتظار فردی را بررسی می‌کنند.',{fr:'attribuer le malentendu à une caractéristique de toute une culture',de:'das Missverständnis einer ganzen Kultur zuzuschreiben',es:'atribuir el malentendido a una característica de toda una cultura'})],
 focus:'در ارتباط بین‌فرهنگی پیش از نتیجه‌گیری دربارهٔ نیت سؤال کنید و تفاوت فردی را به کلیشهٔ ملی تبدیل نکنید.',speaking:'در نقش شریک نخست سوءبرداشت را روشن کنید و برای ثبت موارد باز توافق کنید.',writing:'پیامی محترمانه بنویسید که هدف مشترک، دو تغییر و موارد باز را مشخص کند.',steps:['برداشت اولیه را به شکل پرسش مطرح کنید.','محدودهٔ واقعی تغییر را روشن کنید.','توافق و موارد باز را جدا ثبت کنید.','از تعمیم فرهنگی پرهیز کنید.'],
 model:{fr:'Merci pour votre retour. Lorsque vous dites que l’ordre du jour est à revoir, souhaitez-vous modifier certains points ou tout le programme ? Je comprends maintenant que l’objectif général vous convient et que la durée de deux points doit être discutée. Consignons les éléments approuvés et les questions encore ouvertes, sans supposer une raison culturelle à notre malentendu.',de:'Vielen Dank für Ihre Rückmeldung. Wenn Sie eine Überarbeitung wünschen, meinen Sie einzelne Punkte oder das gesamte Programm? Ich verstehe nun, dass Sie das Gesamtziel unterstützen und die Dauer zweier Punkte besprechen möchten. Halten wir angenommene und offene Punkte schriftlich fest, ohne das Missverständnis pauschal kulturell zu erklären.',es:'Gracias por su respuesta. Cuando dice que hay que revisar el orden del día, ¿se refiere a algunos puntos o a todo el programa? Ahora entiendo que apoya el objetivo general y desea discutir la duración de dos puntos. Dejemos por escrito lo aceptado y lo pendiente, sin atribuir el malentendido de forma general a una cultura.'}
},
{
 number:24,id:'c1-unexpected-response',title:'پاسخ حرفه‌ای در اختلال پیش‌بینی‌نشده',
 passage:{fr:'Au début d’une présentation publique, le système de projection tombe en panne. La conférencière indique calmement qu’elle ne connaît pas encore la durée de l’interruption. Elle propose de résumer oralement les points essentiels et demande si les participants peuvent suivre sans support visuel. Une personne signale que les graphiques sont nécessaires à sa compréhension. L’équipe cherche alors une version accessible à partager et suspend la partie qui dépend des graphiques. La conférencière donne un horaire de mise à jour, sans promettre une réparation avant vérification. Elle maintient les questions ouvertes et note les points à reprendre.',de:'Zu Beginn einer öffentlichen Präsentation fällt der Projektor aus. Die Vortragende erklärt ruhig, dass sie die Dauer der Unterbrechung noch nicht kennt. Sie schlägt vor, die Kernpunkte mündlich zusammenzufassen, und fragt, ob die Teilnehmenden ohne visuelle Unterstützung folgen können. Eine Person erklärt, dass sie die Grafiken zum Verständnis benötigt. Das Team sucht daraufhin eine zugängliche Version zum Teilen und unterbricht den grafischen Teil. Die Vortragende nennt einen Zeitpunkt für eine neue Information, ohne vor der Prüfung eine Reparatur zu versprechen. Offene Fragen werden notiert.',es:'Al comienzo de una presentación pública falla el sistema de proyección. La ponente indica con calma que aún no conoce la duración de la interrupción. Propone resumir oralmente los puntos esenciales y pregunta si los participantes pueden seguir sin apoyo visual. Una persona señala que necesita los gráficos para comprender. El equipo busca entonces una versión accesible para compartir y suspende la parte que depende de los gráficos. La ponente indica cuándo dará una actualización, sin prometer una reparación antes de comprobarla. Se anotan las preguntas pendientes.'},
 questions:[q('چه چیزی دربارهٔ اختلال هنوز معلوم نیست؟',['مدت وقفه','وجود نقص نمایشگر','شروع ارائه'],'مدت وقفه هنوز مشخص نیست.',{fr:'ne connaît pas encore la durée de l’interruption',de:'die Dauer der Unterbrechung noch nicht kennt',es:'aún no conoce la duración de la interrupción'}),q('با بیان نیاز به نمودار چه اقدامی می‌شود؟',['ادامهٔ اجباری بدون دسترسی','جست‌وجوی نسخهٔ دسترس‌پذیر و توقف بخش وابسته','حذف سؤال فرد'],'تیم نسخهٔ قابل دسترس می‌جوید و بخش وابسته را متوقف می‌کند.',{fr:'une version accessible à partager et suspend la partie qui dépend des graphiques',de:'eine zugängliche Version zum Teilen und unterbricht den grafischen Teil',es:'una versión accesible para compartir y suspende la parte que depende de los gráficos'}),q('دربارهٔ تعمیر چه تعهدی داده می‌شود؟',['تعمیر قطعی در پنج دقیقه','پایان قطعی ارائه','زمان اطلاع‌رسانی مشخص می‌شود اما تعمیر تضمین نمی‌شود'],'زمان به‌روزرسانی تعیین می‌شود، نه زمان قطعی تعمیر.',{fr:'sans promettre une réparation avant vérification',de:'ohne vor der Prüfung eine Reparatur zu versprechen',es:'sin prometer una reparación antes de comprobarla'})],
 focus:'در اختلال ناگهانی واقعیت، عدم قطعیت، نیاز دسترسی و زمان پیگیری را روشن بگویید و وعدهٔ تأییدنشده ندهید.',speaking:'در نقش سخنران، اختلال را توضیح و گزینهٔ دسترس‌پذیر و زمان اطلاع‌رسانی را اعلام کنید.',writing:'پیامی کوتاه به شرکت‌کنندگان دربارهٔ وقفه و گام‌های بعدی بنویسید.',steps:['مسئله و مدت نامعلوم را بیان کنید.','نیاز متفاوت مخاطبان را بپرسید.','بخش وابسته و نسخهٔ قابل دسترس را مشخص کنید.','زمان به‌روزرسانی را بدون وعدهٔ تعمیر بدهید.'],
 model:{fr:'Le projecteur est en panne et nous ne connaissons pas encore la durée de l’interruption. Nous pouvons résumer certains points oralement, mais les graphiques restent nécessaires pour une participante. Nous cherchons une version accessible et suspendons la partie concernée. Nous vous informerons de la situation dans quinze minutes, sans pouvoir encore garantir une réparation. Vos questions seront notées pour la reprise.',de:'Der Projektor ist ausgefallen und die Dauer der Unterbrechung ist noch unbekannt. Einige Punkte können wir mündlich zusammenfassen, aber eine Teilnehmerin benötigt die Grafiken. Wir suchen eine zugängliche Version und unterbrechen den betreffenden Teil. In fünfzehn Minuten informieren wir Sie erneut, ohne eine Reparatur garantieren zu können. Ihre Fragen halten wir für die Fortsetzung fest.',es:'El proyector ha fallado y aún no conocemos la duración de la interrupción. Podemos resumir algunos puntos oralmente, pero una participante necesita los gráficos. Buscamos una versión accesible y suspendemos esa parte. Les informaremos de nuevo dentro de quince minutos, sin poder garantizar todavía una reparación. Anotaremos sus preguntas para retomarlas después.'}
},
{
 number:25,id:'c1-negotiated-resolution',title:'حل اختلاف با گزینه و معیار مشترک',
 passage:{fr:'Une association et un propriétaire discutent de l’usage d’une salle. L’association souhaite une réservation tardive ; le propriétaire s’inquiète du bruit pour les voisins. Plutôt que de répéter leurs positions, les deux parties identifient leurs besoins : un temps suffisant pour l’activité et un niveau sonore acceptable. Elles envisagent une fin plus tôt, une mesure du bruit et un essai de deux soirées. Le propriétaire demande de consulter les voisins avant de s’engager ; l’association souhaite vérifier les conditions d’accès. Elles fixent une réunion de suivi, mais aucun accord définitif n’est signé.',de:'Ein Verein und ein Eigentümer verhandeln über die Nutzung eines Raums. Der Verein möchte eine späte Reservierung; der Eigentümer sorgt sich wegen des Lärms für die Nachbarn. Statt ihre Positionen zu wiederholen, benennen beide ihre Bedürfnisse: genügend Zeit für die Veranstaltung und einen akzeptablen Lärmpegel. Sie erwägen ein früheres Ende, eine Lärmmessung und einen Test an zwei Abenden. Der Eigentümer möchte vor einer Zusage die Nachbarn befragen; der Verein will die Zugangsbedingungen prüfen. Ein Folgetreffen wird vereinbart, aber kein endgültiger Vertrag unterzeichnet.',es:'Una asociación y un propietario negocian el uso de una sala. La asociación desea una reserva hasta tarde; el propietario se preocupa por el ruido para los vecinos. En lugar de repetir sus posiciones, ambos identifican sus necesidades: tiempo suficiente para la actividad y un nivel de ruido aceptable. Consideran terminar antes, medir el ruido y hacer una prueba de dos tardes. El propietario pide consultar a los vecinos antes de comprometerse; la asociación quiere comprobar las condiciones de acceso. Acuerdan una reunión de seguimiento, pero no firman todavía un acuerdo definitivo.'},
 questions:[q('دو نیاز اصلی طرفین چیست؟',['زمان کافی فعالیت و صدای قابل قبول','تغییر مالک ساختمان و حذف همسایه‌ها','فقط رنگ صندلی‌ها'],'نیازها زمان فعالیت و سطح صدای قابل قبول‌اند.',{fr:'un temps suffisant pour l’activité et un niveau sonore acceptable',de:'genügend Zeit für die Veranstaltung und einen akzeptablen Lärmpegel',es:'tiempo suficiente para la actividad y un nivel de ruido aceptable'}),q('پیش از تعهد مالک چه باید کند؟',['قرارداد قطعی امضا کند','با همسایگان مشورت کند','سالن را بفروشد'],'مالک پیش از تعهد با همسایگان مشورت می‌خواهد.',{fr:'consulter les voisins avant de s’engager',de:'vor einer Zusage die Nachbarn befragen',es:'consultar a los vecinos antes de comprometerse'}),q('وضعیت توافق چیست؟',['نهایی و امضاشده است','آزمون قبلاً تکمیل شده است','جلسهٔ پیگیری هست اما توافق نهایی امضا نشده'],'جلسه تعیین شده اما توافق نهایی امضا نشده است.',{fr:'aucun accord définitif n’est signé',de:'kein endgültiger Vertrag unterzeichnet',es:'no firman todavía un acuerdo definitivo'})],
 focus:'موضع، نیاز، گزینه، معیار و اختیارات تعهد را جدا کنید؛ گزینهٔ مشروط معادل توافق نهایی نیست.',speaking:'در نقش میانجی نیازهای طرفین و گزینهٔ آزمون را با شرط‌های باز مذاکره کنید.',writing:'خلاصهٔ مذاکره با نیازها، گزینه، مسئول بررسی و وضعیت توافق بنویسید.',steps:['دو نیاز را بدون قضاوت بازگو کنید.','گزینه و معیار سنجش صدا را بنویسید.','مشورت همسایه و بررسی دسترسی را ثبت کنید.','وضعیت باز و جلسهٔ بعد را مشخص کنید.'],
 model:{fr:'L’association a besoin de temps pour son activité et le propriétaire souhaite limiter le bruit pour les voisins. Les parties étudient une fin plus tôt, une mesure sonore et un essai de deux soirées. Le propriétaire consultera les voisins et l’association vérifiera l’accès avant tout engagement. Un suivi est prévu, mais aucun accord définitif n’est signé.',de:'Der Verein benötigt Zeit für seine Veranstaltung, der Eigentümer möchte den Lärm für die Nachbarn begrenzen. Beide prüfen ein früheres Ende, eine Lärmmessung und einen Test an zwei Abenden. Der Eigentümer befragt die Nachbarn und der Verein prüft den Zugang, bevor Zusagen erfolgen. Ein Folgetreffen ist geplant; ein endgültiger Vertrag ist nicht unterzeichnet.',es:'La asociación necesita tiempo para su actividad y el propietario quiere limitar el ruido para los vecinos. Ambas partes estudian terminar antes, medir el ruido y probar durante dos tardes. El propietario consultará a los vecinos y la asociación comprobará el acceso antes de comprometerse. Hay una reunión de seguimiento, pero no se ha firmado un acuerdo definitivo.'}
},
{
 number:26,id:'c1-strategic-proposal',title:'پیشنهاد راهبردی با پیامد و ریسک',
 passage:{fr:'Une bibliothèque doit choisir comment améliorer l’accès numérique avec un budget limité. Une option consiste à acheter davantage d’ordinateurs ; une autre à former des bénévoles pour accompagner les usagers. L’achat pourrait réduire l’attente, mais entraîne des coûts de maintenance. La formation pourrait aider davantage de personnes à utiliser les services, mais nécessite du temps et une disponibilité régulière. Un responsable propose un essai combiné à petite échelle et des indicateurs de coût et d’accès. Il demande aussi de consulter les usagers qui ne fréquentent pas encore la bibliothèque. Le conseil n’a pas encore choisi de stratégie.',de:'Eine Bibliothek muss mit begrenztem Budget den digitalen Zugang verbessern. Eine Option ist der Kauf weiterer Computer; eine andere die Schulung von Freiwilligen zur Unterstützung der Nutzer. Der Kauf könnte Wartezeiten senken, verursacht aber Wartungskosten. Die Schulung könnte mehr Menschen bei der Nutzung helfen, benötigt jedoch Zeit und regelmäßige Verfügbarkeit. Ein Verantwortlicher schlägt einen kleinen kombinierten Test mit Indikatoren zu Kosten und Zugang vor. Er möchte auch Menschen befragen, die die Bibliothek bisher nicht nutzen. Der Rat hat noch keine Strategie gewählt.',es:'Una biblioteca debe mejorar el acceso digital con un presupuesto limitado. Una opción es comprar más ordenadores; otra es formar a voluntarios para acompañar a los usuarios. La compra podría reducir la espera, pero genera costes de mantenimiento. La formación podría ayudar a más personas a utilizar los servicios, pero necesita tiempo y disponibilidad regular. Un responsable propone una prueba combinada a pequeña escala con indicadores de coste y acceso. También pide consultar a quienes todavía no usan la biblioteca. El consejo aún no ha elegido una estrategia.'},
 questions:[q('مزیت احتمالی خرید چیست؟',['کاهش انتظار','حذف همهٔ هزینه‌ها','تضمین استفادهٔ همه'],'خرید ممکن است انتظار را کاهش دهد.',{fr:'pourrait réduire l’attente',de:'könnte Wartezeiten senken',es:'podría reducir la espera'}),q('محدودیت آموزش داوطلبان چیست؟',['هیچ نیرویی لازم ندارد','نیاز به زمان و دسترسی منظم داوطلبان','حذف نیاز به مشورت'],'آموزش به زمان و دسترسی منظم نیاز دارد.',{fr:'nécessite du temps et une disponibilité régulière',de:'benötigt jedoch Zeit und regelmäßige Verfügbarkeit',es:'necesita tiempo y disponibilidad regular'}),q('پیشنهاد برای کاهش عدم قطعیت چیست؟',['انتخاب بدون سنجش','خرید فوری برای همه','آزمون کوچک ترکیبی با شاخص و مشورت'],'آزمون کوچک و مشورت پیشنهاد می‌شود.',{fr:'un essai combiné à petite échelle et des indicateurs de coût et d’accès',de:'einen kleinen kombinierten Test mit Indikatoren zu Kosten und Zugang',es:'una prueba combinada a pequeña escala con indicadores de coste y acceso'})],
 focus:'گزینه‌ها را با منافع، هزینه، ریسک و شاخص قابل اندازه‌گیری مقایسه کنید و نظر افراد خارج از نمونهٔ فعلی را جویا شوید.',speaking:'دو گزینه و یک آزمون راهبردی را برای شورا با ریسک و شاخص ارائه دهید.',writing:'پیشنهادی مشروط با مقایسهٔ گزینه‌ها، شاخص ارزیابی و مشورت بنویسید.',steps:['هدف و محدودیت بودجه را بیان کنید.','مزیت و هزینهٔ هر گزینه را مقایسه کنید.','آزمون و شاخص‌ها را مشخص کنید.','مشورت و تصمیم باز را ثبت کنید.'],
 model:{fr:'L’achat de matériel pourrait réduire l’attente, mais il entraîne des frais de maintenance. La formation de bénévoles pourrait améliorer l’accompagnement, à condition de disposer de temps et d’une présence régulière. Je propose un essai combiné limité, avec mesure des coûts et de l’accès, ainsi qu’une consultation de personnes qui n’utilisent pas encore la bibliothèque. Le conseil pourra comparer les résultats avant de choisir une stratégie.',de:'Der Kauf könnte Wartezeiten verkürzen, verursacht aber Wartungskosten. Die Schulung Freiwilliger könnte die Unterstützung verbessern, sofern Zeit und regelmäßige Verfügbarkeit vorhanden sind. Ich schlage einen begrenzten kombinierten Test mit Kosten- und Zugangsindikatoren sowie eine Befragung bisheriger Nichtnutzer vor. Der Rat kann die Ergebnisse vor der Wahl einer Strategie vergleichen.',es:'La compra podría reducir la espera, pero implica costes de mantenimiento. La formación de voluntarios podría mejorar el acompañamiento si hay tiempo y disponibilidad regular. Propongo una prueba combinada limitada con indicadores de coste y acceso, además de consultar a quienes aún no usan la biblioteca. El consejo podrá comparar los resultados antes de elegir una estrategia.'}
},
{
 number:28,id:'c1-multifaceted-analysis',title:'تحلیل مستقل مسئلهٔ چندوجهی',
 passage:{fr:'Une ville souhaite planter des arbres dans une place très fréquentée. Les habitants espèrent davantage d’ombre, mais certains commerçants craignent une réduction de l’espace de livraison. Une architecte rappelle que les racines peuvent affecter les réseaux souterrains et que l’entretien exige un budget régulier. Un groupe de riverains demande également des bancs accessibles. Aucun plan détaillé ni devis complet n’est disponible. La ville décide de cartographier les réseaux, d’étudier plusieurs implantations et de consulter les personnes concernées. Elle ne présente pas la plantation comme une solution qui résoudra seule tous les problèmes de chaleur.',de:'Eine Stadt möchte auf einem stark genutzten Platz Bäume pflanzen. Bewohner erhoffen sich mehr Schatten, einige Geschäftsleute befürchten jedoch weniger Platz für Lieferungen. Eine Architektin weist darauf hin, dass Wurzeln unterirdische Leitungen beeinträchtigen können und die Pflege ein regelmäßiges Budget erfordert. Eine Anwohnergruppe fordert auch barrierefreie Sitzbänke. Ein detaillierter Plan und ein vollständiger Kostenvoranschlag fehlen. Die Stadt will Leitungen kartieren, mehrere Standorte prüfen und Betroffene befragen. Sie stellt die Bepflanzung nicht als alleinige Lösung aller Hitzeprobleme dar.',es:'Una ciudad quiere plantar árboles en una plaza muy transitada. Los vecinos esperan más sombra, pero algunos comerciantes temen perder espacio de carga. Una arquitecta recuerda que las raíces pueden afectar a las redes subterráneas y que el mantenimiento requiere un presupuesto regular. Un grupo de residentes pide también bancos accesibles. No hay un plano detallado ni un presupuesto completo. La ciudad decide cartografiar las redes, estudiar varias ubicaciones y consultar a las personas afectadas. No presenta la plantación como una solución que resolverá por sí sola todos los problemas de calor.'},
 questions:[q('نگرانی کسبه چیست؟',['کاهش فضای تحویل کالا','نبود برنامهٔ آموزش زبان','قیمت کتابخانه'],'برخی کسبه نگران فضای تحویل کالا هستند.',{fr:'une réduction de l’espace de livraison',de:'weniger Platz für Lieferungen',es:'perder espacio de carga'}),q('کدام هزینه یا خطر باید بررسی شود؟',['فقط طراحی پوستر','شبکه‌های زیرزمینی و بودجهٔ نگهداری','هیچ خطر یا هزینه‌ای وجود ندارد'],'ریشه‌ها و هزینهٔ نگهداری باید بررسی شوند.',{fr:'les racines peuvent affecter les réseaux souterrains et que l’entretien exige un budget régulier',de:'Wurzeln unterirdische Leitungen beeinträchtigen können und die Pflege ein regelmäßiges Budget erfordert',es:'las raíces pueden afectar a las redes subterráneas y que el mantenimiento requiere un presupuesto regular'}),q('وضعیت راه‌حل چیست؟',['کاشت همهٔ مشکل گرما را به‌تنهایی حل می‌کند','طرح و بودجهٔ کامل تأیید شده','طرح و داده‌ها هنوز باید بررسی و با افراد مشورت شود'],'چند گزینه و اطلاعات فنی باید بررسی شوند.',{fr:'cartographier les réseaux, d’étudier plusieurs implantations et de consulter les personnes concernées',de:'Leitungen kartieren, mehrere Standorte prüfen und Betroffene befragen',es:'cartografiar las redes, estudiar varias ubicaciones y consultar a las personas afectadas'})],
 focus:'مسئلهٔ چندوجهی را با منافع و محدودیت گروه‌های مختلف، داده‌های غایب و پیامدهای ناخواسته تحلیل کنید.',speaking:'برای شورا منافع سایه، نگرانی کسبه، خطر فنی و گام بررسی را توضیح دهید.',writing:'تحلیلی چندوجهی با منافع، ریسک‌ها، دادهٔ غایب و پیشنهاد مشورت بنویسید.',steps:['هدف و منفعت مورد انتظار را بیان کنید.','نیازهای کسبه و ساکنان را مقایسه کنید.','شبکه‌ها و هزینهٔ نگهداری را بررسی کنید.','طرح جایگزین و مشورت را بدون نتیجهٔ قطعی پیشنهاد دهید.'],
 model:{fr:'La plantation pourrait apporter de l’ombre, mais elle peut réduire l’espace de livraison et affecter les réseaux souterrains. Le budget d’entretien et les besoins de bancs accessibles doivent aussi être pris en compte. Sans plan ni devis complets, une décision définitive serait prématurée. Il faut cartographier les réseaux, comparer des implantations et consulter les habitants et commerçants.',de:'Die Pflanzung könnte Schatten schaffen, aber Lieferflächen einschränken und unterirdische Leitungen beeinträchtigen. Auch Pflegekosten und der Bedarf an barrierefreien Bänken sind zu berücksichtigen. Ohne vollständigen Plan und Kostenvoranschlag wäre eine endgültige Entscheidung verfrüht. Leitungen sollten kartiert, Standorte verglichen und Bewohner sowie Geschäftsleute befragt werden.',es:'La plantación podría aportar sombra, pero también reducir el espacio de carga y afectar a redes subterráneas. Hay que considerar el mantenimiento y la necesidad de bancos accesibles. Sin un plano ni un presupuesto completos sería prematuro decidir. Conviene cartografiar las redes, comparar ubicaciones y consultar a residentes y comerciantes.'}
},
{
 number:29,id:'c1-reconstruct-argument',title:'بازسازی منصفانه و نقد استدلال دیگری',
 passage:{fr:'Lors d’un débat, Hugo affirme qu’une bibliothèque devrait fermer le matin parce que les visites de l’après-midi sont plus nombreuses. Avant de répondre, Sara reformule sa position : il veut concentrer les ressources sur la période la plus fréquentée. Hugo confirme cette description. Sara demande ensuite si les visites du matin concernent des personnes qui ne peuvent pas venir plus tard et si les coûts varient selon l’horaire. Elle reconnaît que les chiffres de fréquentation sont utiles, mais souligne qu’ils ne suffisent pas à évaluer l’accès. Elle propose de recueillir ces données avant de recommander une fermeture.',de:'In einer Debatte behauptet Hugo, eine Bibliothek solle morgens schließen, weil nachmittags mehr Besuche stattfinden. Vor ihrer Antwort formuliert Sara seine Position neu: Er möchte die Ressourcen auf die stärker genutzte Zeit konzentrieren. Hugo bestätigt diese Darstellung. Sara fragt anschließend, ob morgens Menschen kommen, die später nicht kommen können, und ob die Kosten je nach Zeit variieren. Sie erkennt an, dass Besucherzahlen nützlich sind, betont aber, dass sie für eine Bewertung des Zugangs nicht ausreichen. Sie schlägt vor, diese Daten vor einer Schließungsempfehlung zu erheben.',es:'En un debate, Hugo afirma que una biblioteca debería cerrar por la mañana porque por la tarde recibe más visitas. Antes de responder, Sara reformula su posición: quiere concentrar recursos en el periodo más utilizado. Hugo confirma esa descripción. Después Sara pregunta si por la mañana acuden personas que no pueden venir más tarde y si los costes varían según el horario. Reconoce que las cifras de visitas son útiles, pero señala que no bastan para evaluar el acceso. Propone recoger esos datos antes de recomendar un cierre.'},
 questions:[q('سارا پیش از نقد چه می‌کند؟',['استدلال هوگو را بازسازی و تأیید او را می‌گیرد','به شخصیت هوگو حمله می‌کند','داده‌ها را حذف می‌کند'],'او ابتدا موقعیت هوگو را بازگو و تأیید می‌گیرد.',{fr:'reformule sa position',de:'formuliert Sara seine Position neu',es:'Sara reformula su posición'}),q('کدام محدودیت در نقد مطرح می‌شود؟',['تعداد بازدید کاملاً بی‌فایده است','شمار بازدید به‌تنهایی دسترسی کاربران صبح را روشن نمی‌کند','همهٔ کاربران صبح می‌توانند عصر بیایند'],'شمار بازدید به تنهایی نشان نمی‌دهد کاربران صبح گزینهٔ دیگری دارند.',{fr:'ils ne suffisent pas à évaluer l’accès',de:'sie für eine Bewertung des Zugangs nicht ausreichen',es:'no bastan para evaluar el acceso'}),q('پیشنهاد پیش از توصیهٔ تعطیلی چیست؟',['بستن فوری','رد هر دادهٔ مربوط به هزینه','گردآوری دادهٔ دسترسی و هزینه'],'پیش از توصیه باید دادهٔ بیشتر جمع شود.',{fr:'recueillir ces données avant de recommander une fermeture',de:'diese Daten vor einer Schließungsempfehlung zu erheben',es:'recoger esos datos antes de recomendar un cierre'})],
 focus:'پیش از نقد استدلال دیگران، موضع آنها را منصفانه بازسازی و تأیید کنید؛ اعتبار بخشی از شواهد به معنی پذیرش نتیجه نیست.',speaking:'در نقش سارا استدلال هوگو را بازگو کنید، تأیید بگیرید و دو سؤال دربارهٔ دسترسی و هزینه بپرسید.',writing:'بازسازی و نقدی منصفانه با دادهٔ لازم پیش از تصمیم بنویسید.',steps:['موضع را بدون تحریف خلاصه کنید.','اعتبار بخشی از شواهد را بپذیرید.','شکاف دسترسی و هزینه را مشخص کنید.','گردآوری داده پیش از توصیه را پیشنهاد دهید.'],
 model:{fr:'Vous proposez de concentrer les ressources sur l’après-midi, lorsque la bibliothèque reçoit plus de visites. Est-ce bien votre position ? Les chiffres sont utiles, mais ils ne montrent pas si les usagers du matin peuvent venir plus tard ni comment les coûts varient. Avant de recommander la fermeture, recueillons ces données et consultons les personnes concernées.',de:'Sie schlagen vor, die Ressourcen auf den stärker besuchten Nachmittag zu konzentrieren. Habe ich Ihre Position richtig verstanden? Die Zahlen sind nützlich, zeigen aber nicht, ob morgendliche Nutzer später kommen können oder wie die Kosten variieren. Vor einer Schließungsempfehlung sollten wir diese Daten erheben und Betroffene befragen.',es:'Propone concentrar los recursos en la tarde, cuando hay más visitas. ¿He entendido bien su posición? Las cifras son útiles, pero no muestran si los usuarios de la mañana pueden acudir después ni cómo varían los costes. Antes de recomendar el cierre conviene recoger esos datos y consultar a las personas afectadas.'}
},
{
 number:30,id:'c1-independent-communication',title:'مدیریت مستقل ارتباط پیچیده',
 passage:{fr:'Une coordinatrice organise un projet entre une université, une association et une entreprise. L’université souhaite publier un bilan, l’association protège les témoignages des participants et l’entreprise doit respecter un calendrier financier. Après une réunion, la coordinatrice envoie à chaque partie un résumé des objectifs, des responsabilités et des points encore ouverts. Elle précise que les témoignages ne seront pas publiés sans accord et que le calendrier dépend de vérifications. Elle propose une réunion pour comparer les options et invite les destinataires à corriger toute erreur dans le résumé. Aucun accord final n’est présenté comme acquis.',de:'Eine Koordinatorin organisiert ein Projekt zwischen einer Universität, einem Verein und einem Unternehmen. Die Universität möchte einen Bericht veröffentlichen, der Verein schützt Aussagen der Teilnehmenden und das Unternehmen muss einen Finanzierungszeitplan einhalten. Nach einer Sitzung sendet die Koordinatorin allen Parteien eine Zusammenfassung der Ziele, Zuständigkeiten und offenen Punkte. Sie erklärt, dass Aussagen nicht ohne Einwilligung veröffentlicht werden und der Zeitplan von Prüfungen abhängt. Sie schlägt ein Treffen zum Vergleich der Optionen vor und bittet um Korrekturen der Zusammenfassung. Eine endgültige Einigung wird nicht als gegeben dargestellt.',es:'Una coordinadora organiza un proyecto entre una universidad, una asociación y una empresa. La universidad desea publicar un balance, la asociación protege los testimonios de los participantes y la empresa debe cumplir un calendario de financiación. Después de una reunión, la coordinadora envía a cada parte un resumen de objetivos, responsabilidades y puntos pendientes. Aclara que no se publicarán testimonios sin consentimiento y que el calendario depende de comprobaciones. Propone una reunión para comparar opciones e invita a corregir cualquier error del resumen. No presenta un acuerdo final como si ya existiera.'},
 questions:[q('کدام دغدغهٔ انجمن باید حفظ شود؟',['حفاظت از شهادت‌های شرکت‌کنندگان','حذف همهٔ مسئولیت‌ها','انتشار بی‌رضایت'],'انجمن بر حفاظت از شهادت‌ها تأکید دارد.',{fr:'l’association protège les témoignages des participants',de:'der Verein schützt Aussagen der Teilnehmenden',es:'la asociación protege los testimonios de los participantes'}),q('زمان‌بندی چه وضعیتی دارد؟',['قطعی و مستقل از بررسی است','به بررسی‌ها وابسته است','در متن نیامده است'],'زمان‌بندی به بررسی‌ها وابسته است.',{fr:'le calendrier dépend de vérifications',de:'der Zeitplan von Prüfungen abhängt',es:'el calendario depende de comprobaciones'}),q('هماهنگ‌کننده چه اقدامی برای کنترل برداشت انجام می‌دهد؟',['توافق نهایی را بدون تأیید اعلام می‌کند','اصلاح خلاصه را ممنوع می‌کند','دعوت به اصلاح خلاصه و مقایسهٔ گزینه‌ها'],'او اصلاح خلاصه و مقایسهٔ گزینه‌ها را پیشنهاد می‌کند.',{fr:'invite les destinataires à corriger toute erreur dans le résumé',de:'bittet um Korrekturen der Zusammenfassung',es:'invita a corregir cualquier error del resumen'})],
 focus:'در ارتباط چندطرفه هدف، مسئولیت، محرمانگی، شرط زمان‌بندی و امکان اصلاح برداشت را هم‌زمان مدیریت کنید.',speaking:'در نقش هماهنگ‌کننده خلاصهٔ سه دیدگاه را بیان و برای جلسهٔ بعد دعوت کنید.',writing:'پیام مشترکی بنویسید که منافع، خط قرمز رضایت، موارد باز و گام بعدی را روشن کند.',steps:['هدف هر طرف را منصفانه بازگو کنید.','رضایت برای انتشار را مشخص کنید.','وابستگی زمان‌بندی و موارد باز را بنویسید.','دعوت به اصلاح و جلسهٔ بعد را اضافه کنید.'],
 model:{fr:'L’université souhaite publier un bilan, l’association protège les témoignages et l’entreprise doit respecter son calendrier financier. Aucun témoignage ne sera publié sans accord ; les dates dépendent encore des vérifications. Je propose une réunion pour comparer les options et répartir les tâches restantes. Merci de signaler toute erreur dans ce résumé. Aucun accord final n’est encore conclu.',de:'Die Universität möchte einen Bericht veröffentlichen, der Verein schützt Aussagen und das Unternehmen muss seinen Finanzierungszeitplan beachten. Aussagen werden nicht ohne Einwilligung veröffentlicht; die Termine hängen noch von Prüfungen ab. Ich schlage ein Treffen vor, um Optionen zu vergleichen und offene Aufgaben zu verteilen. Bitte korrigieren Sie Fehler in dieser Zusammenfassung. Eine endgültige Einigung besteht noch nicht.',es:'La universidad desea publicar un balance, la asociación protege los testimonios y la empresa debe respetar su calendario de financiación. No se publicarán testimonios sin consentimiento; las fechas dependen aún de comprobaciones. Propongo una reunión para comparar opciones y repartir tareas pendientes. Por favor, indiquen cualquier error en este resumen. Todavía no hay un acuerdo final.'}
},
];
export const c1SurvivalExpansion:readonly TopicDeepening[]=entries.map(entry=>{
 const questions=entry.questions.map((question,i)=>{const correctIndex=i;const choices=[...question.answers.slice(1)];choices.splice(correctIndex,0,question.answers[0]);return {prompt:question.prompt,choices,correctIndex,explanation:question.explanation,evidence:question.evidence};});
 const comparison=getC1SurvivalLanguageNote(entry.number);
 if(!comparison)throw new Error(`Missing C1 survival language note ${entry.number}`);
 const note=(lang:keyof Local)=>({explanation:`${entry.focus} ${comparison.explanation}`,first:comparison.examples[lang][0],second:comparison.examples[lang][1],difference:comparison.difference,phrases:entry.questions.map(question=>({text:question.evidence[lang],meaning:`شاهد پاسخ: ${question.explanation}`}))});
 const notes={fr:note('fr'),de:note('de'),es:note('es')};
 return {id:entry.id,level:'c1',section:'survival',number:entry.number,title:entry.title,passage:entry.passage,questions,notes,speaking:entry.speaking,writing:entry.writing,steps:entry.steps,model:entry.model};
});
